/* ===== UTILITY FUNCTIONS ===== */
function t(k){return T[S.lang][k]||k;}
var PLAN_META={
  free:{key:'free',nameAr:'مجاني',nameEn:'Free',price:0,photos:6,packages:4,badge:''},
  basic:{key:'basic',nameAr:'Basic',nameEn:'Basic',price:400,photos:25,packages:'unlimited',badge:'badge1'},
  premium:{key:'premium',nameAr:'Premium',nameEn:'Premium',price:600,photos:40,packages:'unlimited',badge:'badge2'}
};
function planPrice(plan){
  var settings=S.siteSettings||{};
  if(plan==='premium')return Number(settings.premiumPlanPriceEgp||PLAN_META.premium.price);
  if(plan==='basic')return Number(settings.basicPlanPriceEgp||settings.subscriptionPriceEgp||PLAN_META.basic.price);
  return 0;
}
function normalizePlanKey(value){
  value=String(value||'').toLowerCase();
  return value==='premium'?'premium':(value==='basic'?'basic':'free');
}
function profilePlan(profile){
  if(!profile||profile.isSubscribed!==true)return'free';
  return normalizePlanKey(profile.subscriptionPlan||profile.subscription_plan||'basic');
}
function activePlan(){
  return profilePlan(S.user);
}
function planName(plan){
  var meta=PLAN_META[normalizePlanKey(plan)]||PLAN_META.free;
  return S.lang==='ar'?meta.nameAr:meta.nameEn;
}
function planLimitText(plan,type){
  plan=normalizePlanKey(plan);
  var meta=PLAN_META[plan]||PLAN_META.free;
  if(type==='photos')return meta.photos+' '+(S.lang==='ar'?'صورة':'images');
  if(type==='packages')return meta.packages==='unlimited'?(S.lang==='ar'?'باقات غير محدودة':'Unlimited packages'):(meta.packages+' '+(S.lang==='ar'?'باقات':'packages'));
  return'';
}
function renderPlanBadge(profile){
  var plan=profilePlan(profile);
  if(plan==='free')return'';
  var premium=plan==='premium';
  return '<span class="profile-plan-badge '+(premium?'profile-plan-premium':'profile-plan-basic')+'">'+
    '<i class="fas '+(premium?'fa-crown':'fa-award')+'"></i>'+
    '<span>'+(premium?(S.lang==='ar'?'Premium':'Premium'):(S.lang==='ar'?'Basic':'Basic'))+'</span>'+
  '</span>';
}
function deepCopy(v){return JSON.parse(JSON.stringify(v));}
function apiToken(){
  try{return localStorage.getItem('dof_api_token')||'';}catch(e){return'';}
}
function setApiToken(token){
  try{
    if(token)localStorage.setItem('dof_api_token',token);
    else localStorage.removeItem('dof_api_token');
  }catch(e){}
}
function saveApiProfile(profile){
  try{
    if(profile)localStorage.setItem('dof_api_profile',JSON.stringify(profile));
    else localStorage.removeItem('dof_api_profile');
  }catch(e){}
}
function readApiProfile(){
  try{
    var raw=localStorage.getItem('dof_api_profile');
    return raw?JSON.parse(raw):null;
  }catch(e){return null;}
}
function authUser(){
  var p=readApiProfile();
  return p?normalizeProfile(p):S.user;
}
async function apiRequest(path,options){
  options=options||{};
  var headers=options.headers||{};
  headers['Content-Type']=headers['Content-Type']||'application/json';
  var token=apiToken();
  if(token)headers.Authorization='Bearer '+token;
  var res=await fetch(path,{method:options.method||'GET',headers:headers,body:options.body?JSON.stringify(options.body):undefined});
  var text=await res.text();
  var data={};
  
  // محاولة تحليل JSON مع معالجة الأخطاء
  if(text){
    try{
      data=JSON.parse(text);
    }catch(jsonError){
      console.error('JSON Parse Error:', jsonError);
      console.error('Response Text:', text);
      // إذا كان النص يبدأ بـ HTML، فهو صفحة خطأ من الخادم
      if(text.trim().startsWith('<')){
        throw new Error('خطأ في الخادم - تم إرجاع صفحة HTML بدلاً من JSON');
      }
      // خطأ JSON عام
      throw new Error('خطأ في تحليل استجابة الخادم: ' + jsonError.message);
    }
  }
  
  if(!res.ok){
    var msg=(data.error&&data.error.message)||'Request failed';
    throw new Error(msg);
  }
  return data;
}
function slugifyCategory(value){
  return String(value||'').toLowerCase().trim().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
}
function fallbackCategories(){
  return (S.photographyTypes||[]).map(function(type){
    return {id:type.id,slug:type.id,en:type.en,ar:type.ar,icon:type.icon,isActive:true,sortOrder:0};
  });
}
function normalizeCategoryRecord(row){
  if(!row)return null;
  var en=row.nameEn||row.name_en||row.en||row.name||row.slug||'';
  var ar=row.nameAr||row.name_ar||row.ar||en;
  var slug=row.slug||row.id||slugifyCategory(en);
  var fallback=(S.photographyTypes||[]).find(function(type){return type.id===slug;});
  return {
    id:String(row.id||slug),
    slug:String(slug),
    en:en,
    ar:ar,
    icon:row.icon||(fallback&&fallback.icon)||'fa-camera',
    isActive:row.isActive!==false&&row.is_active!==false,
    sortOrder:Number(row.sortOrder||row.sort_order||0)
  };
}
function categoryOptions(){
  var rows=(S.categories&&S.categories.length?S.categories:fallbackCategories()).map(normalizeCategoryRecord).filter(Boolean);
  return rows.filter(function(row){return row.isActive!==false;});
}
function findCategory(slug){
  var wanted=String(slug||'');
  return categoryOptions().find(function(cat){return cat.slug===wanted||cat.id===wanted;})||null;
}
function categoryLabel(category,lang){
  var row=normalizeCategoryRecord(category);
  if(!row)return'';
  return (lang||S.lang)==='ar'?(row.ar||row.en):(row.en||row.ar);
}
function categoryTextValue(category,lang){
  var row=normalizeCategoryRecord(category);
  if(!row)return'';
  return (lang||'en')==='ar'?(row.ar||row.en):(row.en||row.ar);
}
function normalizeCategoryList(raw,slugs,legacyEn,legacyAr){
  var rows=[];
  if(Array.isArray(raw)){
    rows=raw.map(normalizeCategoryRecord).filter(Boolean);
  }
  if(rows.length===0&&Array.isArray(slugs)){
    rows=slugs.map(findCategory).filter(Boolean);
  }
  if(rows.length===0&&(legacyEn||legacyAr)){
    var text=[legacyEn,legacyAr].join(' ');
    var normalized=' '+normalizeCategoryText(text)+' ';
    rows=categoryOptions().filter(function(cat){
      var terms=[cat.slug,cat.en,cat.ar,normalizeCategoryText(cat.en),normalizeCategoryText(cat.ar)];
      return terms.some(function(term){
        var clean=normalizeCategoryText(term);
        return clean&&normalized.indexOf(' '+clean+' ')>-1;
      });
    });
  }
  var bySlug={};
  return rows.filter(function(row){
    if(!row||bySlug[row.slug])return false;
    bySlug[row.slug]=true;
    return true;
  });
}
