function normalizeProfile(profile){
  if(!profile)return null;
  var pp=Array.isArray(profile.photographer_profiles)?profile.photographer_profiles[0]:profile.photographer_profiles;
  var rawCategories=pp?(pp.categories||[]):(profile.categories||[]);
  var rawSlugs=pp?(pp.category_slugs||pp.categorySlugs):(profile.category_slugs||profile.categorySlugs);
  var categories=normalizeCategoryList(rawCategories,rawSlugs,pp?(pp.specialty||''):(profile.specialty||''),profile.specialtyAr||'');
  var specialtyEn=categories.length?categories.map(function(cat){return categoryTextValue(cat,'en');}).join(', '):(pp?(pp.specialty||'Photography'):(profile.specialty||'Photography'));
  var specialtyAr=categories.length?categories.map(function(cat){return categoryTextValue(cat,'ar');}).join('، '):(profile.specialtyAr||(pp?(pp.specialty||'تصوير'):'تصوير'));
  var subscriptionStatus=pp?(pp.subscription_status||'free'):(profile.subscriptionStatus||profile.subscription_status||'free');
  var subscriptionPlan=pp?(pp.subscription_plan||''):(profile.subscriptionPlan||profile.subscription_plan||'');
  if(subscriptionStatus==='active'&&!subscriptionPlan)subscriptionPlan='basic';
  if(subscriptionStatus!=='active')subscriptionPlan='free';
  var normalizedSubscriptionPlan=normalizePlanKey(subscriptionPlan);
  var hasPaidSubscription=subscriptionStatus==='active'&&(normalizedSubscriptionPlan==='basic'||normalizedSubscriptionPlan==='premium');
  return {
    id:profile.id,email:profile.email,role:profile.role,
    name:profile.display_name||profile.name||'',
    nameAr:profile.display_name||profile.nameAr||profile.name||'',
    phone:profile.phone||'',avatar:profile.avatar_url||profile.avatar||'',
    specialty:specialtyEn,
    specialtyAr:specialtyAr,
    categories:categories,
    categorySlugs:categories.map(function(cat){return cat.slug;}),
    region:pp?(pp.region||'cairo'):(profile.region||'cairo'),
    regionAr:pp?(pp.region||'القاهرة'):(profile.regionAr||'القاهرة'),
    customLink:pp?(pp.custom_link||''):(profile.customLink||''),
    bio:pp?(pp.bio||''):(profile.bio||''),
    bioAr:pp?(pp.bio||''):(profile.bioAr||''),
    cover:pp?(pp.cover_url||''):(profile.cover||''),
    coverPosition:normalizeCoverPosition(pp?(pp.cover_position||profile.coverPosition):(profile.cover_position||profile.coverPosition)),
    social:pp?(pp.social_links||{}):(profile.social||{}),
    rating:profile.rating||0,bookings:profile.booking_count||0,
    subscriptionDueAt:pp?(pp.subscription_due_at||pp.subscription_ends_at):null,
    portfolioSuspended:pp?pp.is_suspended===true:false,
    subscriptionStatus:subscriptionStatus,
    subscriptionPlan:hasPaidSubscription?normalizedSubscriptionPlan:'free',
    isSubscribed:hasPaidSubscription,
    isPublished:pp?pp.is_published===true:false,
    trialStartedAt:pp?(pp.trial_started_at||null):(profile.trialStartedAt||profile.trial_started_at||null),
    createdAt:pp?pp.created_at:profile.created_at||null
  };
}
