function renderWorkingHoursCard(){
  var wh=S.workingHours||[
    {dayOfWeek:1,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:2,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:3,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:4,startTime:'08:00',endTime:'14:00',enabled:true},
    {dayOfWeek:5,startTime:'08:00',endTime:'14:00',enabled:true}
  ];
  var labels=S.lang==='ar'?['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت']:['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  return'<div class="card p-5 mb-6"><div class="flex flex-wrap items-center justify-between gap-3 mb-4"><div><h3 class="font-bold">'+(S.lang==='ar'?'ساعات العمل':'Working Hours')+'</h3><p class="text-xs text-[var(--text2)]">'+(S.lang==='ar'?'هذه الساعات تحدد المواعيد المتاحة للحجز الفوري':'These hours control instant booking availability')+'</p></div><button onclick="saveWorkingHours()" class="btn-primary btn-sm">'+t('save')+'</button></div>'+
  '<div class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">'+[0,1,2,3,4,5,6].map(function(day){
    var item=wh.find(function(x){return Number(x.dayOfWeek)===day;})||{dayOfWeek:day,startTime:'08:00',endTime:'14:00',enabled:false};
    return'<div class="p-3 rounded-lg bg-[var(--bg2)] border border-[var(--border)]"><label class="flex items-center gap-2 text-sm font-semibold mb-2"><input type="checkbox" class="wh-enabled" data-day="'+day+'" '+(item.enabled?'checked':'')+'> '+labels[day]+'</label><div class="grid grid-cols-2 gap-2"><input type="time" class="input wh-start" data-day="'+day+'" value="'+item.startTime+'"><input type="time" class="input wh-end" data-day="'+day+'" value="'+item.endTime+'"></div></div>';
  }).join('')+'</div></div>';
}
async function saveWorkingHours(){
  var rows=[];
  document.querySelectorAll('.wh-enabled').forEach(function(chk){
    var day=Number(chk.dataset.day);
    rows.push({
      dayOfWeek:day,
      enabled:chk.checked,
      startTime:(document.querySelector('.wh-start[data-day="'+day+'"]')||{}).value||'08:00',
      endTime:(document.querySelector('.wh-end[data-day="'+day+'"]')||{}).value||'14:00'
    });
  });
  for(var i=0;i<rows.length;i++){
    if(!rows[i].startTime||!rows[i].endTime||rows[i].startTime>=rows[i].endTime){
      showToast(S.lang==='ar'?'وقت النهاية يجب أن يكون بعد وقت البداية':'End time must be after start time','error');
      return;
    }
  }
  try{
    if(apiToken())await apiRequest('/api/availability/working-hours',{method:'PUT',body:{workingHours:rows}});
    S.workingHours=rows;
    renderTab();
    showToast(S.lang==='ar'?'تم حفظ ساعات العمل':'Working hours saved','success');
  }catch(err){showToast(err.message||'تعذر حفظ ساعات العمل','error');}
}
function changeMonth(dir){S.calMonth+=dir;if(S.calMonth>11){S.calMonth=0;S.calYear++;}if(S.calMonth<0){S.calMonth=11;S.calYear--;}S.selectedDate=null;renderTab();}
function selectCalDate(ds){S.selectedDate=ds;renderTab();}
function addMinutesToTimeInput(time,minutes){
  var parts=String(time||'').split(':');
  if(parts.length<2)return'';
  var total=(parseInt(parts[0],10)||0)*60+(parseInt(parts[1],10)||0)+Number(minutes||0);
  total=Math.max(0,Math.min(23*60+59,total));
  return String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0');
}
function getAptSelectedPackage(){
  var select=document.getElementById('apt-package');
  if(!select||!select.value)return null;
  return (S.packages||[]).find(function(p){return String(p.id)===String(select.value);})||null;
}
function populateAptPackageOptions(){
  var select=document.getElementById('apt-package');
  if(!select)return;
  var packages=(S.packages||[]).slice().sort(function(a,b){return String(gf(a,'name')||'').localeCompare(String(gf(b,'name')||''));});
  select.innerHTML=packages.length
    ? packages.map(function(p){return'<option value="'+p.id+'">'+escapeHtml(gf(p,'name')||'')+' — '+formatMoney(p.price)+'</option>';}).join('')
    : '<option value="">'+(S.lang==='ar'?'لا توجد باقات':'No packages yet')+'</option>';
}
function fillAptPackageDetails(){
  var mode=(document.getElementById('apt-service-mode')||{}).value||'package';
  if(mode!=='package')return;
  var pkg=getAptSelectedPackage();
  var end=document.getElementById('apt-end');
  var start=document.getElementById('apt-start');
  var summary=document.getElementById('apt-package-summary');
  if(!pkg){
    if(summary)summary.textContent=S.lang==='ar'?'أنشئ باقة أو اختر حجز مخصص':'Create a package or switch to custom booking';
    return;
  }
  if(start&&end&&start.value)end.value=addMinutesToTimeInput(start.value,pkg.durationMinutes||60);
  if(summary)summary.textContent=(S.lang==='ar'?'السعر: ':'Price: ')+formatMoney(pkg.price)+' • '+(S.lang==='ar'?'المدة: ':'Duration: ')+gf(pkg,'duration');
}
function toggleAptServiceMode(){
  var mode=(document.getElementById('apt-service-mode')||{}).value||'package';
  var packageWrap=document.getElementById('apt-package-wrap');
  var customWrap=document.getElementById('apt-custom-wrap');
  var service=document.getElementById('apt-service');
  var price=document.getElementById('apt-price');
  var end=document.getElementById('apt-end');
  var usePackage=mode==='package';
  if(packageWrap)packageWrap.classList.toggle('hidden',!usePackage);
  if(customWrap)customWrap.classList.toggle('hidden',usePackage);
  if(service){service.required=!usePackage;service.disabled=usePackage;}
  if(price){price.required=!usePackage;price.disabled=usePackage;}
  if(end){end.required=!usePackage;end.readOnly=usePackage;}
  if(usePackage)fillAptPackageDetails();
}
function applyAptClientSelection(clientId){
  if(!clientId)return;
  var select=document.getElementById('apt-client-account');
  if(!select)return;
  select.value=String(clientId);
  if(select.value===String(clientId))fillAptClientFromSelect();
}
function openAptModal(preselectClientId){
  var today = todayLocalISO();
  var form=document.querySelector('#apt-modal form');
  if(form)form.reset();
  var date=document.getElementById('apt-date');
  if(date){date.min=today;date.value=S.selectedDate || today;}
  var start=document.getElementById('apt-start');
  var end=document.getElementById('apt-end');
  if(start&&!start.value)start.value='10:00';
  if(end&&!end.value)end.value='11:00';
  populateAptPackageOptions();
  var mode=document.getElementById('apt-service-mode');
  if(mode)mode.value=(S.packages||[]).length?'package':'custom';
  toggleAptServiceMode();
  populateAptClientOptions();
  applyAptClientSelection(preselectClientId);
  if(apiToken()&&S.user&&S.user.role==='photographer'){
    refreshConversations().then(function(){
      populateAptClientOptions();
      applyAptClientSelection(preselectClientId);
    }).catch(function(){});
  }
  openModal('apt-modal');
}
function aptKnownClients(){
  var byId={};
  (S.bookings||[]).forEach(function(b){
    if(!b.clientId)return;
    byId[b.clientId]={id:b.clientId,name:b.clientName||'Client',email:b.clientEmail||'',phone:b.clientPhone||''};
  });
  (S.conversations||[]).forEach(function(c){
    if(!c.clientId)return;
    if(!byId[c.clientId])byId[c.clientId]={id:c.clientId,name:c.clientName||'Client',email:'',phone:''};
    else if(!byId[c.clientId].name)byId[c.clientId].name=c.clientName||'Client';
  });
  return Object.keys(byId).map(function(id){return byId[id];}).sort(function(a,b){return a.name.localeCompare(b.name);});
}
function populateAptClientOptions(){
  var select=document.getElementById('apt-client-account');
  if(!select)return;
  var current=select.value;
  var label=S.lang==='ar'?'بدون ربط - بيانات تواصل فقط':'No linked client - contact only';
  var options='<option value="">'+label+'</option>'+aptKnownClients().map(function(c){
    return'<option value="'+c.id+'" data-name="'+escapeHtml(c.name||'')+'" data-email="'+escapeHtml(c.email||'')+'" data-phone="'+escapeHtml(c.phone||'')+'">'+escapeHtml(c.name||'Client')+'</option>';
  }).join('');
  select.innerHTML=options;
  if(current)select.value=current;
}
function fillAptClientFromSelect(){
  var select=document.getElementById('apt-client-account');
  if(!select||!select.value)return;
  var opt=select.options[select.selectedIndex];
  var name=document.getElementById('apt-client');
  var email=document.getElementById('apt-email');
  var phone=document.getElementById('apt-phone');
  if(name&&opt.dataset.name)name.value=opt.dataset.name;
  if(email&&opt.dataset.email)email.value=opt.dataset.email;
  if(phone&&opt.dataset.phone)phone.value=opt.dataset.phone;
}
async function handleAddApt(e){
  e.preventDefault();
  if(!apiToken()||!S.user||S.user.role!=='photographer'){showToast(S.lang==='ar'?'سجل الدخول كمصور أولاً':'Sign in as a photographer first','error');return;}
  var start=document.getElementById('apt-start').value;
  var end=document.getElementById('apt-end').value;
  var mode=(document.getElementById('apt-service-mode')||{}).value||'package';
  var packageId=(document.getElementById('apt-package')||{}).value||'';
  if(!start){showToast(S.lang==='ar'?'اختر وقت البداية':'Select a start time','error');return;}
  if(mode==='package'&&!packageId){showToast(S.lang==='ar'?'اختر باقة أو استخدم الحجز المخصص':'Choose a package or switch to custom','error');return;}
  if(mode==='custom'&&(!end||start>=end)){showToast(S.lang==='ar'?'وقت النهاية يجب أن يكون بعد وقت البداية':'End time must be after start time','error');return;}
  if(mode==='custom'&&!document.getElementById('apt-service').value.trim()){showToast(S.lang==='ar'?'اكتب اسم الخدمة':'Enter a service name','error');return;}
  if(mode==='custom'&&!document.getElementById('apt-price').value){showToast(S.lang==='ar'?'اكتب السعر':'Enter a price','error');return;}
  var btn=e.target.querySelector('button[type="submit"]');
  if(btn){btn.disabled=true;btn.classList.add('opacity-60');}
  try{
    var selectedClient=document.getElementById('apt-client-account');
    var payload={
      clientId:selectedClient&&selectedClient.value?selectedClient.value:null,
      clientName:document.getElementById('apt-client').value,
      clientEmail:document.getElementById('apt-email').value,
      clientPhone:document.getElementById('apt-phone').value,
      date:document.getElementById('apt-date').value,
      startTime:start,
      notes:document.getElementById('apt-notes').value
    };
    if(mode==='package'){
      payload.packageId=packageId;
    }else{
      payload.endTime=end;
      payload.serviceName=document.getElementById('apt-service').value;
      payload.price=document.getElementById('apt-price').value;
    }
    var res=await apiRequest('/api/bookings/manual',{method:'POST',body:payload});
    var booking=normalizeBooking(res.booking);
    S.bookings=S.bookings.filter(function(b){return String(b.id)!==String(booking.id);});
    S.bookings.push(booking);
    S.appointments=S.appointments.filter(function(a){return String(a.id)!==String(booking.id);});
    S.appointments.push({id:booking.id,date:booking.date,time:booking.time,client:booking.clientName,clientPhone:booking.clientPhone,clientEmail:booking.clientEmail,service:booking.service,status:'confirmed',notes:booking.notes||''});
    if(res.conversationId){await refreshConversations().catch(function(){});}
    S.selectedDate=booking.date;
    closeModal('apt-modal');
    renderTab();
    showToast(S.lang==='ar'?'تم إضافة الحجز':'Booking added','success');
  }catch(err){
    showToast(err.message||'تعذر إضافة الحجز','error');
  }finally{
    if(btn){btn.disabled=false;btn.classList.remove('opacity-60');}
  }
}

