async function updateProfile(e){
  e.preventDefault();var u=S.user;
  var nameVal=document.getElementById('s-nameAr').value;
  var bioVal=document.getElementById('s-bioAr').value;
  var customLinkVal=slugifyProfileLink((document.getElementById('s-custom-link')||{}).value||'');
  var selectedCategories=(S.settingsCategorySlugs||[]).slice();
  if(!selectedCategories.length){showToast(S.lang==='ar'?'اختر قسماً واحداً على الأقل':'Choose at least one category','error');return;}
  if(customLinkVal.length<3){showToast(S.lang==='ar'?'رابط الملف يجب أن يكون 3 أحرف على الأقل':'Profile link must be at least 3 characters','error');return;}
  var specValEn=categorySummaryFromSlugs(selectedCategories,'en')||u.specialty||'Photography';
  var specValAr=categorySummaryFromSlugs(selectedCategories,'ar')||u.specialtyAr||specValEn;
  u.name=nameVal;u.nameAr=nameVal;
  u.specialty=specValEn;u.specialtyAr=specValAr;
  u.categories=selectedCategoryRows(selectedCategories);
  u.categorySlugs=selectedCategories;
  u.bio=bioVal;u.bioAr=bioVal;
  u.customLink=customLinkVal;
  var dirPhoto=S.photographers.find(function(p){return p.id===u.id;});
  if(dirPhoto){Object.assign(dirPhoto,{name:nameVal,nameAr:nameVal,specialty:specValEn,specialtyAr:specValAr,categories:u.categories,categorySlugs:selectedCategories,bio:bioVal,bioAr:bioVal,customLink:customLinkVal});}
  updateSidebarUser();
  try{
    await apiRequest('/api/me/profile',{method:'PATCH',body:{displayName:nameVal,categorySlugs:selectedCategories,bio:bioVal,customLink:customLinkVal}});
    var stored=readApiProfile();
    if(stored){
      if(Array.isArray(stored.photographer_profiles)&&stored.photographer_profiles[0])stored.photographer_profiles[0].custom_link=customLinkVal;
      else if(stored.photographer_profiles)stored.photographer_profiles.custom_link=customLinkVal;
      saveApiProfile(stored);
    }
    showToast('تم تحديث الملف الشخصي','success');
  }catch(err){showToast(err.message||'فشل الحفظ','error');}
}
async function togglePublishProfile(){
  if(!S.user||S.user.role!=='photographer')return;
  var next=!(S.user.isPublished===true);
  try{
    await apiRequest('/api/me/profile',{method:'PATCH',body:{isPublished:next}});
    S.user.isPublished=next;
    showToast(next?(S.lang==='ar'?'تم نشر ملفك':'Profile published'):(S.lang==='ar'?'تم إخفاء ملفك':'Profile hidden'),'success');
    renderTab();
  }catch(err){showToast(err.message||'فشل التحديث','error');}
}
async function updateSocial(){
  if(!S.user.social)S.user.social={};
  S.user.social.instagram=document.getElementById('s-instagram').value;
  S.user.social.facebook=document.getElementById('s-facebook').value;
  S.user.social.whatsapp=document.getElementById('s-whatsapp').value;
  var dirPhoto=S.photographers.find(function(p){return p.id===S.user.id;});
  if(dirPhoto)dirPhoto.social=S.user.social;
  try{
    await apiRequest('/api/me/profile',{method:'PATCH',body:{socialLinks:{instagram:S.user.social.instagram,facebook:S.user.social.facebook,whatsapp:S.user.social.whatsapp}}});
    showToast(S.lang==='ar'?'تم تحديث روابط التواصل':'Social links updated','success');
  }catch(err){showToast(err.message||'فشل الحفظ','error');}
}
function openMediaPicker(type){
  var id=type==='cover'?'s-cover-input':'s-avatar-input';
  var input=document.getElementById(id);
  if(input){input.click();}
}
function handleMediaFile(type,input){
  var file=input&&input.files&&input.files[0];
  if(!file)return;
  if(!/^image\//.test(file.type)){showToast(S.lang==='ar'?'يرجى اختيار صورة فقط':'Please select an image file','error');input.value='';return;}
  if(file.size>5*1024*1024){showToast(S.lang==='ar'?'الحد الأقصى 5MB':'Max file size is 5MB','error');input.value='';return;}
  input.value='';
  var reader=new FileReader();
  reader.onload=function(e){
    if(type==='cover'){
      openCoverPositionModal(e.target.result,file);
      return;
    }
    if(type==='avatar'){
      openAvatarPositionModal(e.target.result,file);
      return;
    }
    applyMediaUpdate(type,e.target.result);
    uploadMediaFile(type,file);
  };
  reader.readAsDataURL(file);
}
async function uploadMediaFile(type,file,coverPosition){
  try{
    var sign=await apiRequest('/api/uploads/sign',{method:'POST',body:{kind:'portfolio',filename:file.name}});
    var res=await fetch(sign.signedUrl,{method:'PUT',headers:{'Content-Type':file.type},body:file});
    if(!res.ok)throw new Error('Upload failed');
    var patch=type==='cover'?{coverUrl:sign.publicUrl,coverPosition:normalizeCoverPosition(coverPosition||S.user.coverPosition)}:{avatarUrl:sign.publicUrl};
    await apiRequest('/api/me/profile',{method:'PATCH',body:patch});
    applyMediaUpdate(type,sign.publicUrl,coverPosition);
    saveFrontendSession();
    showToast(type==='cover'?(S.lang==='ar'?'تم تحديث صورة البانر':'Banner updated'):(S.lang==='ar'?'تم تحديث صورة البروفايل':'Profile photo updated'),'success');
  }catch(err){
    saveFrontendSession();
    showToast(S.lang==='ar'?'تم الحفظ مؤقتاً — فشل الرفع':'Saved locally — upload failed','warning');
  }
}
async function uploadProfileCoverDataUrl(dataUrl,coverPosition){
  var pos=normalizeCoverPosition(coverPosition);
  var data=await apiRequest('/api/me/profile/media',{method:'POST',body:{type:'cover',dataUrl:dataUrl,coverPosition:pos}});
  applyMediaUpdate('cover',data.publicUrl,pos,{silent:true});
  saveFrontendSession();
  showToast(S.lang==='ar'?'تم تحديث صورة البانر':'Banner updated','success');
  return data;
}
function applyMediaUpdate(type,dataUrl,coverPosition,options){
  if(!S.user)return;
  if(type==='cover'){S.user.cover=dataUrl;S.user.coverPosition=normalizeCoverPosition(coverPosition||S.user.coverPosition);}
  else{S.user.avatar=dataUrl;}
  var dirPhoto=S.photographers.find(function(p){return p.id===S.user.id;});
  if(dirPhoto){
    if(type==='cover'){dirPhoto.cover=S.user.cover;dirPhoto.coverPosition=S.user.coverPosition;}
    else{dirPhoto.avatar=S.user.avatar;}
  }
  if(S.view==='public'||S.isPortfolioPreview){renderPublicProfile();}
  if(S.view==='dashboard'){renderTab();}
  updateSidebarUser();
  if(!(options&&options.silent)){
    showToast(type==='cover'?(S.lang==='ar'?'تم تحديث صورة البانر':'Banner image updated'):(S.lang==='ar'?'تم تحديث صورة البروفايل':'Profile photo updated'),'success');
  }
}
function ensureCoverPositionModal(){
  var modal=document.getElementById('cover-position-modal');
  if(modal)return modal;
  modal=document.createElement('div');
  modal.id='cover-position-modal';
  modal.className='modal-overlay cover-position-modal';
  modal.innerHTML='<div class="modal-box lg cover-position-box">'+
    '<div class="flex justify-between items-center mb-4"><h3 class="text-xl font-bold">'+(S.lang==='ar'?'قص البانر':'Crop Cover')+'</h3>'+
    '<button onclick="closeCoverPositionModal()" class="text-[var(--text2)] hover:text-[var(--text)] text-xl"><i class="fas fa-times"></i></button></div>'+
    '<div class="cover-position-frame" id="cover-position-frame"><img id="cover-position-img" alt=""><div class="cover-crop-box" id="cover-crop-box"><span class="cover-crop-handle" id="cover-crop-handle"></span></div></div>'+
    '<div class="cover-position-actions">'+
    '<button type="button" class="btn-secondary btn-sm" onclick="resetCoverCrop()">'+(S.lang==='ar'?'إعادة':'Reset')+'</button>'+
    '<button type="button" class="btn-primary btn-sm" onclick="confirmCoverPosition()">'+(S.lang==='ar'?'حفظ':'Save')+'</button>'+
    '</div></div>';
  document.body.appendChild(modal);
  return modal;
}
function openCoverPositionModal(src,file){
  if(!S.user)return;
  var imageSrc=src||S.user.cover;
  if(!imageSrc){openMediaPicker('cover');return;}
  S.coverPositionDraft={src:imageSrc,file:file||null,position:'50% 50%',crop:null};
  var modal=ensureCoverPositionModal();
  var img=document.getElementById('cover-position-img');
  if(img){
    img.crossOrigin='anonymous';
    img.onload=function(){resetCoverCrop();};
    img.src=imageSrc;
  }
  modal.classList.add('active');
  document.body.style.overflow='hidden';
  bindCoverPositionDrag();
}
function closeCoverPositionModal(){
  var modal=document.getElementById('cover-position-modal');
  if(modal)modal.classList.remove('active');
  document.body.style.overflow='';
  S.coverPositionDraft=null;
}
function coverCropImageRect(){
  var frame=document.getElementById('cover-position-frame');
  var img=document.getElementById('cover-position-img');
  if(!frame||!img)return null;
  var fr=frame.getBoundingClientRect();
  var ir=img.getBoundingClientRect();
  if(!ir.width||!ir.height)return null;
  return {left:ir.left-fr.left,top:ir.top-fr.top,width:ir.width,height:ir.height};
}
function applyCoverCropBox(){
  var box=document.getElementById('cover-crop-box');
  var crop=S.coverPositionDraft&&S.coverPositionDraft.crop;
  if(!box||!crop)return;
  box.style.display='block';
  box.style.left=crop.x+'px';
  box.style.top=crop.y+'px';
  box.style.width=crop.w+'px';
  box.style.height=crop.h+'px';
}
function setCoverCropRect(rect){
  if(!S.coverPositionDraft)return;
  var bounds=coverCropImageRect();
  if(!bounds)return;
  var aspect=16/7;
  var minW=Math.min(140,bounds.width);
  var w=Math.max(minW,Math.min(rect.w,bounds.width));
  var h=w/aspect;
  if(h>bounds.height){
    h=bounds.height;
    w=h*aspect;
  }
  var x=Math.max(bounds.left,Math.min(rect.x,bounds.left+bounds.width-w));
  var y=Math.max(bounds.top,Math.min(rect.y,bounds.top+bounds.height-h));
  S.coverPositionDraft.crop={x:x,y:y,w:w,h:h};
  applyCoverCropBox();
}
function resetCoverCrop(){
  if(!S.coverPositionDraft)return;
  var bounds=coverCropImageRect();
  if(!bounds){setTimeout(resetCoverCrop,60);return;}
  var aspect=16/7;
  var w=bounds.width*.86;
  var h=w/aspect;
  if(h>bounds.height*.86){
    h=bounds.height*.86;
    w=h*aspect;
  }
  setCoverCropRect({x:bounds.left+(bounds.width-w)/2,y:bounds.top+(bounds.height-h)/2,w:w,h:h});
}
function bindCoverPositionDrag(){
  var frame=document.getElementById('cover-position-frame');
  var box=document.getElementById('cover-crop-box');
  var handle=document.getElementById('cover-crop-handle');
  if(!frame||frame.dataset.bound==='1')return;
  frame.dataset.bound='1';
  var drag=null;
  function beginDrag(mode,e){
    if(!S.coverPositionDraft||!S.coverPositionDraft.crop)return;
    e.preventDefault();
    var point=e.touches&&e.touches[0]?e.touches[0]:e;
    drag={mode:mode,startX:point.clientX,startY:point.clientY,start:Object.assign({},S.coverPositionDraft.crop)};
  }
  function moveDrag(e){
    if(!drag)return;
    var point=e.touches&&e.touches[0]?e.touches[0]:e;
    var dx=point.clientX-drag.startX;
    var dy=point.clientY-drag.startY;
    if(drag.mode==='move'){
      setCoverCropRect({x:drag.start.x+dx,y:drag.start.y+dy,w:drag.start.w,h:drag.start.h});
    }else{
      var delta=Math.abs(dx)>Math.abs(dy*16/7)?dx:dy*16/7;
      setCoverCropRect({x:drag.start.x,y:drag.start.y,w:drag.start.w+delta,h:drag.start.h+(delta*7/16)});
    }
  }
  if(box)box.addEventListener('pointerdown',function(e){if(e.target===handle)return;beginDrag('move',e);});
  if(handle)handle.addEventListener('pointerdown',function(e){beginDrag('resize',e);});
  window.addEventListener('pointermove',moveDrag);
  window.addEventListener('pointerup',function(){drag=null;});
  window.addEventListener('resize',function(){
    var modal=document.getElementById('cover-position-modal');
    if(modal&&modal.classList.contains('active'))resetCoverCrop();
  });
}
function exportCoverCropBlob(){
  return new Promise(function(resolve,reject){
    var draft=S.coverPositionDraft;
    var img=document.getElementById('cover-position-img');
    var bounds=coverCropImageRect();
    if(!draft||!draft.crop||!img||!bounds||!img.naturalWidth){reject(new Error('Crop is not ready'));return;}
    try{
      var crop=draft.crop;
      var sx=((crop.x-bounds.left)/bounds.width)*img.naturalWidth;
      var sy=((crop.y-bounds.top)/bounds.height)*img.naturalHeight;
      var sw=(crop.w/bounds.width)*img.naturalWidth;
      var sh=(crop.h/bounds.height)*img.naturalHeight;
      var canvas=document.createElement('canvas');
      canvas.width=1600;
      canvas.height=700;
      var ctx=canvas.getContext('2d');
      ctx.drawImage(img,sx,sy,sw,sh,0,0,canvas.width,canvas.height);
      canvas.toBlob(function(blob){
        if(blob)resolve(blob);
        else reject(new Error('Unable to crop this image'));
      },'image/jpeg',0.92);
    }catch(err){reject(err);}
  });
}
function blobToDataUrl(blob){
  return new Promise(function(resolve,reject){
    var reader=new FileReader();
    reader.onload=function(){resolve(reader.result);};
    reader.onerror=function(){reject(reader.error||new Error('Unable to read crop'));};
    reader.readAsDataURL(blob);
  });
}
function coverCropFileName(file){
  var base=file&&file.name?file.name.replace(/\.[^.]+$/,''):'cover';
  return base+'-cropped-cover.jpg';
}
async function confirmCoverPosition(){
  if(!S.coverPositionDraft||!S.user)return;
  var previousCover=S.user.cover;
  var previousPosition=S.user.coverPosition;
  var preview;
  try{
    var blob=await exportCoverCropBlob();
    preview=await blobToDataUrl(blob);
  }catch(err){
    showToast(S.lang==='ar'?'تعذر قص هذه الصورة، أعد رفع الصورة الأصلية':'Could not crop this image. Re-upload the original image.','error');
    return;
  }
  closeCoverPositionModal();
  applyMediaUpdate('cover',preview,'50% 50%',{silent:true});
  try{
    await uploadProfileCoverDataUrl(preview,'50% 50%');
  }catch(err){
    applyMediaUpdate('cover',previousCover,previousPosition,{silent:true});
    saveFrontendSession();
    var msg = S.lang === 'ar' ? 'فشل رفع البانر: ' : 'Cover upload failed: ';
    showToast(msg + (err.message || 'Unknown error'), 'error');
  }
}
function ensureAvatarPositionModal(){
  var modal=document.getElementById('avatar-position-modal');
  if(modal)return modal;
  modal=document.createElement('div');
  modal.id='avatar-position-modal';
  modal.className='modal-overlay avatar-position-modal';
  modal.innerHTML='<div class="modal-box lg avatar-position-box">'+
    '<div class="flex justify-between items-center mb-4"><h3 class="text-xl font-bold">'+(S.lang==='ar'?'قص الصورة الشخصية':'Crop Avatar')+'</h3>'+
    '<button onclick="closeAvatarPositionModal()" class="text-[var(--text2)] hover:text-[var(--text)] text-xl"><i class="fas fa-times"></i></button></div>'+
    '<div class="avatar-position-frame" id="avatar-position-frame"><img id="avatar-position-img" alt=""><div class="avatar-crop-box" id="avatar-crop-box"><span class="avatar-crop-handle" id="avatar-crop-handle"></span></div></div>'+
    '<div class="avatar-position-actions flex justify-end gap-3 mt-4">'+
    '<button type="button" class="btn-secondary btn-sm" onclick="resetAvatarCrop()">'+(S.lang==='ar'?'إعادة':'Reset')+'</button>'+
    '<button type="button" class="btn-primary btn-sm" onclick="confirmAvatarPosition()">'+(S.lang==='ar'?'حفظ':'Save')+'</button>'+
    '</div></div>';
  document.body.appendChild(modal);
  return modal;
}
function openAvatarPositionModal(src,file){
  if(!S.user)return;
  var imageSrc=src||S.user.avatar;
  if(!imageSrc){openMediaPicker('avatar');return;}
  S.avatarPositionDraft={src:imageSrc,file:file||null,crop:null};
  var modal=ensureAvatarPositionModal();
  var img=document.getElementById('avatar-position-img');
  if(img){
    img.crossOrigin='anonymous';
    img.onload=function(){resetAvatarCrop();};
    img.src=imageSrc;
  }
  modal.classList.add('active');
  document.body.style.overflow='hidden';
  bindAvatarPositionDrag();
}
function closeAvatarPositionModal(){
  var modal=document.getElementById('avatar-position-modal');
  if(modal)modal.classList.remove('active');
  document.body.style.overflow='';
  S.avatarPositionDraft=null;
}
function avatarCropImageRect(){
  var frame=document.getElementById('avatar-position-frame');
  var img=document.getElementById('avatar-position-img');
  if(!frame||!img)return null;
  var fr=frame.getBoundingClientRect();
  var ir=img.getBoundingClientRect();
  if(!ir.width||!ir.height)return null;
  return {left:ir.left-fr.left,top:ir.top-fr.top,width:ir.width,height:ir.height};
}
function applyAvatarCropBox(){
  var box=document.getElementById('avatar-crop-box');
  var crop=S.avatarPositionDraft&&S.avatarPositionDraft.crop;
  if(!box||!crop)return;
  box.style.display='block';
  box.style.left=crop.x+'px';
  box.style.top=crop.y+'px';
  box.style.width=crop.w+'px';
  box.style.height=crop.h+'px';
}
function setAvatarCropRect(rect){
  if(!S.avatarPositionDraft)return;
  var bounds=avatarCropImageRect();
  if(!bounds)return;
  var aspect=1;
  var minW=Math.min(100,bounds.width);
  var w=Math.max(minW,Math.min(rect.w,bounds.width));
  var h=w/aspect;
  if(h>bounds.height){
    h=bounds.height;
    w=h*aspect;
  }
  var x=Math.max(bounds.left,Math.min(rect.x,bounds.left+bounds.width-w));
  var y=Math.max(bounds.top,Math.min(rect.y,bounds.top+bounds.height-h));
  S.avatarPositionDraft.crop={x:x,y:y,w:w,h:h};
  applyAvatarCropBox();
}
function resetAvatarCrop(){
  if(!S.avatarPositionDraft)return;
  var bounds=avatarCropImageRect();
  if(!bounds){setTimeout(resetAvatarCrop,60);return;}
  var aspect=1;
  var w=Math.min(bounds.width,bounds.height)*.86;
  var h=w/aspect;
  setAvatarCropRect({x:bounds.left+(bounds.width-w)/2,y:bounds.top+(bounds.height-h)/2,w:w,h:h});
}
function bindAvatarPositionDrag(){
  var frame=document.getElementById('avatar-position-frame');
  var box=document.getElementById('avatar-crop-box');
  var handle=document.getElementById('avatar-crop-handle');
  if(!frame||frame.dataset.bound==='1')return;
  frame.dataset.bound='1';
  var drag=null;
  function beginDrag(mode,e){
    if(!S.avatarPositionDraft||!S.avatarPositionDraft.crop)return;
    e.preventDefault();
    var point=e.touches&&e.touches[0]?e.touches[0]:e;
    drag={mode:mode,startX:point.clientX,startY:point.clientY,start:Object.assign({},S.avatarPositionDraft.crop)};
  }
  function moveDrag(e){
    if(!drag)return;
    var point=e.touches&&e.touches[0]?e.touches[0]:e;
    var dx=point.clientX-drag.startX;
    var dy=point.clientY-drag.startY;
    if(drag.mode==='move'){
      setAvatarCropRect({x:drag.start.x+dx,y:drag.start.y+dy,w:drag.start.w,h:drag.start.h});
    }else{
      var delta=Math.abs(dx)>Math.abs(dy)?dx:dy;
      setAvatarCropRect({x:drag.start.x,y:drag.start.y,w:drag.start.w+delta,h:drag.start.h+delta});
    }
  }
  if(box)box.addEventListener('pointerdown',function(e){if(e.target===handle)return;beginDrag('move',e);});
  if(handle)handle.addEventListener('pointerdown',function(e){beginDrag('resize',e);});
  window.addEventListener('pointermove',moveDrag);
  window.addEventListener('pointerup',function(){drag=null;});
  window.addEventListener('resize',function(){
    var modal=document.getElementById('avatar-position-modal');
    if(modal&&modal.classList.contains('active'))resetAvatarCrop();
  });
}
function exportAvatarCropBlob(){
  return new Promise(function(resolve,reject){
    var draft=S.avatarPositionDraft;
    var img=document.getElementById('avatar-position-img');
    var bounds=avatarCropImageRect();
    if(!draft||!draft.crop||!img||!bounds||!img.naturalWidth){reject(new Error('Crop is not ready'));return;}
    try{
      var crop=draft.crop;
      var sx=((crop.x-bounds.left)/bounds.width)*img.naturalWidth;
      var sy=((crop.y-bounds.top)/bounds.height)*img.naturalHeight;
      var sw=(crop.w/bounds.width)*img.naturalWidth;
      var sh=(crop.h/bounds.height)*img.naturalHeight;
      var canvas=document.createElement('canvas');
      canvas.width=500;
      canvas.height=500;
      var ctx=canvas.getContext('2d');
      ctx.drawImage(img,sx,sy,sw,sh,0,0,canvas.width,canvas.height);
      canvas.toBlob(function(blob){
        if(blob)resolve(blob);
        else reject(new Error('Unable to crop this image'));
      },'image/jpeg',0.92);
    }catch(err){reject(err);}
  });
}
async function confirmAvatarPosition(){
  if(!S.avatarPositionDraft||!S.user)return;
  var previousAvatar=S.user.avatar;
  var preview;
  var blob;
  try{
    blob=await exportAvatarCropBlob();
    preview=await blobToDataUrl(blob);
  }catch(err){
    showToast(S.lang==='ar'?'تعذر قص هذه الصورة، أعد رفع الصورة الأصلية':'Could not crop this image. Re-upload the original image.','error');
    return;
  }
  closeAvatarPositionModal();
  applyMediaUpdate('avatar',preview);
  try{
    var croppedFile = new File([blob], 'avatar-cropped.jpg', { type: 'image/jpeg' });
    await uploadMediaFile('avatar',croppedFile);
  }catch(err){
    applyMediaUpdate('avatar',previousAvatar);
    saveFrontendSession();
  }
}
