function promptLoginToBook(){
  /* Stash whatever booking info has been picked so far so we can restore after login */
  var serviceSel=document.getElementById('pub-service');
  var dateSel=document.getElementById('pub-date');
  var nameInp=document.getElementById('pub-name');
  var emailInp=document.getElementById('pub-email');
  var phoneInp=document.getElementById('pub-phone');
  var phFor=S.viewedPhotographer||S.user;
  var intent={
    photographerId:phFor&&phFor.id?phFor.id:null,
    photographerLink:phFor&&phFor.customLink?phFor.customLink:null,
    packageId:serviceSel?serviceSel.value:'',
    date:dateSel?dateSel.value:'',
    time:S.selectedTime||'',
    clientName:nameInp?nameInp.value:'',
    clientEmail:emailInp?emailInp.value:'',
    clientPhone:phoneInp?phoneInp.value:'',
    savedAt:Date.now()
  };
  try{sessionStorage.setItem('dof_pending_booking_intent',JSON.stringify(intent));}catch(e){}
  /* Default to client signup since they're trying to book */
  S.regRole='client';
  switchAuthTab('register');
  openModal('auth-modal');
}
function restorePendingBookingIntent(){
  if(!S.user||S.user.role!=='client')return;
  var raw='';try{raw=sessionStorage.getItem('dof_pending_booking_intent')||'';}catch(e){return;}
  if(!raw)return;
  var intent;try{intent=JSON.parse(raw);}catch(e){return;}
  /* expire after 30 minutes */
  if(!intent||!intent.savedAt||Date.now()-intent.savedAt>30*60*1000){
    try{sessionStorage.removeItem('dof_pending_booking_intent');}catch(e){}
    return;
  }
  try{sessionStorage.removeItem('dof_pending_booking_intent');}catch(e){}
  if(!intent.photographerLink){return;}
  /* Navigate back to the same photographer profile and rehydrate the form */
  apiRequest('/api/photographers/'+encodeURIComponent(intent.photographerLink)).then(function(data){
    if(!setViewedPhotographerFromApi(data))return;
    navigate('public');
    setTimeout(function(){
      var svc=document.getElementById('pub-service');
      if(svc&&intent.packageId){svc.value=intent.packageId;onPubServiceChange();}
      var dt=document.getElementById('pub-date');
      if(dt&&intent.date){setPublicDateValue(intent.date);onPubDateChange().then(function(){
        if(intent.time){S.selectedTime=intent.time;}
        // Automatically trigger booking if we have all info
        if(intent.clientName || S.user.name) {
          handlePublicBooking({ preventDefault: function(){} });
        }
      });}
      
      var nameInp=document.getElementById('pub-name');
      if(nameInp && (intent.clientName || S.user.name)) nameInp.value=intent.clientName || S.user.name || S.user.nameAr || '';
      
      var emailInp=document.getElementById('pub-email');
      if(emailInp && (intent.clientEmail || S.user.email)) emailInp.value=intent.clientEmail || S.user.email || '';
      
      var phoneInp=document.getElementById('pub-phone');
      if(phoneInp && (intent.clientPhone || S.user.phone)) phoneInp.value=intent.clientPhone || S.user.phone || '';

      scrollToBookingForm();
    },300);
  }).catch(function(){});
}
async function handlePublicBooking(e){
  e.preventDefault();
  // Allow guest bookings! No login prompt required.
  if(!S.selectedTime){showToast(t('noTimes'),'error');return;}
  var selectedPkg=getPackageById(document.getElementById('pub-service').value);
  if(!selectedPkg){showToast(t('selectService'),'error');return;}
  var bookingDate=(document.getElementById('pub-date')||{}).value||'';
  if(!bookingDate){showToast(S.lang==='ar'?'اختر التاريخ بصيغة يوم/شهر/سنة':'Choose a date in day/month/year format','error');return;}
  if(!S.bookings)S.bookings=[];
  var phFor=S.viewedPhotographer||S.user;
  var newBooking={id:++S.nextId,clientName:document.getElementById('pub-name').value,
    clientEmail:document.getElementById('pub-email').value,clientPhone:document.getElementById('pub-phone').value,date:bookingDate,
    time:S.selectedTime,serviceId:selectedPkg.id,service:gf(selectedPkg,'name'),servicePrice:selectedPkg.price,serviceDuration:gf(selectedPkg,'duration'),
    photographerName:gf(phFor,'name'),photographerAvatar:phFor.avatar||phFor.cover,status:'pending'};
  try{
    if(phFor&&phFor.id){
      var data=await apiRequest('/api/bookings',{method:'POST',body:{
        photographerId:phFor.id,packageId:selectedPkg.id,date:newBooking.date,startTime:S.selectedTime,
        clientName:newBooking.clientName,clientEmail:newBooking.clientEmail,clientPhone:newBooking.clientPhone,
        notes:''
      }});
      newBooking=normalizeBooking(data.booking);
      newBooking.service=gf(selectedPkg,'name');
      newBooking.servicePrice=selectedPkg.price;
      newBooking.serviceDuration=gf(selectedPkg,'duration');
      newBooking.photographerName=gf(phFor,'name');
    }
    S.bookings.push(newBooking);
    renderClientBookingsPanel();
    addCustomerRecord(newBooking);
    // notifyPhotographerWhatsApp(newBooking,phFor); // Disabled as requested so it only goes to portfolio
  }catch(err){showToast(err.message||'فشل الحجز','error');return;}
  var conf=document.getElementById('pub-booking-confirmation');
  if(conf){
    conf.innerHTML='<div class="font-semibold text-[var(--success)] mb-1">'+(S.lang==='ar'?'تم إرسال طلب الحجز':'Booking request sent')+'</div>'+
    '<div class="text-sm text-[var(--text2)]">'+(S.lang==='ar'?'الخدمة: ':'Service: ')+newBooking.service+' • '+(S.lang==='ar'?'السعر: ':'Price: ')+'<span class="font-bold">'+formatMoney(newBooking.servicePrice)+'</span></div>'+
    '<button type="button" class="btn-secondary btn-sm mt-3" onclick="startAnotherBooking(\''+newBooking.serviceId+'\')">'+(S.lang==='ar'?'احجز موعد آخر':'Book Another Appointment')+'</button>';
    conf.classList.remove('hidden');
  }
  showToast(t('bookingSuccess'),'success');
  document.getElementById('pub-time-area').classList.add('hidden');
  document.getElementById('pub-service-preview').classList.remove('hidden');
  document.getElementById('pub-package-detail').classList.add('hidden');
  e.target.reset();
  S.selectedTime=null;
  S.selectedShootType=null;
  /* Clear shoot type selector */
  var selector=document.getElementById('shoot-type-selector');
  if(selector){
    selector.querySelectorAll('button').forEach(function(btn){btn.classList.remove('active');});
  }
  window.scrollTo({top:0,behavior:'smooth'});
}

