/* ===== LOCATION DETECTION SYSTEM ===== */
function detectUserLocation(){
  if(!navigator.geolocation){
    showToast(S.lang==='ar'?'المتصفح لا يدعم تحديد الموقع':'Geolocation not supported','error');
    return;
  }
  
  S.isDetectingLocation=true;
  showToast(t('searchingLocation'),'info');
  
  navigator.geolocation.getCurrentPosition(function(position){
    var lat=position.coords.latitude;
    var lng=position.coords.longitude;
    S.detectedLocation={lat:lat,lng:lng};
    
    var nearestRegion=findNearestRegion(lat,lng);
    S.selectedRegion=nearestRegion.id;
    
    S.isDetectingLocation=false;
    showToast((S.lang==='ar'?'تم تحديد موقعك في ':'Location detected: ')+(S.lang==='ar'?nearestRegion.nameAr:nearestRegion.nameEn),'success');
    
    if(S.view==='explore'){
      renderExplorePage();
    }
  },function(error){
    S.isDetectingLocation=false;
    var errorMsg=S.lang==='ar'?'تعذر تحديد الموقع':'Could not detect location';
    switch(error.code){
      case error.PERMISSION_DENIED:
        errorMsg=S.lang==='ar'?'تم رفض إذن الموقع':'Location permission denied';
        break;
      case error.POSITION_UNAVAILABLE:
        errorMsg=S.lang==='ar'?'معلومات الموقع غير متاحة':'Location information unavailable';
        break;
      case error.TIMEOUT:
        errorMsg=S.lang==='ar'?'انتهت مهلة تحديد الموقع':'Location request timed out';
        break;
    }
    showToast(errorMsg,'error');
  },{
    enableHighAccuracy:true,
    timeout:10000,
    maximumAge:300000
  });
}

function findNearestRegion(lat,lng){
  var regions=S.egyptRegions;
  var nearest=null;
  var minDist=Infinity;
  
  for(var i=0;i<regions.length;i++){
    var r=regions[i];
    var dist=getDistance(lat,lng,r.lat,r.lng);
    if(dist<minDist){
      minDist=dist;
      nearest=r;
    }
  }
  
  return nearest||regions[0];
}

function getDistance(lat1,lng1,lat2,lng2){
  var R=6371;
  var dLat=(lat2-lat1)*Math.PI/180;
  var dLng=(lng2-lng1)*Math.PI/180;
  var a=Math.sin(dLat/2)*Math.sin(dLat/2)+
    Math.cos(lat1*Math.PI/180)*Math.cos(lat2*Math.PI/180)*
    Math.sin(dLng/2)*Math.sin(dLng/2);
  var c=2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));
  return R*c;
}

function selectRegion(regionId){
  S.selectedRegion=regionId;
  var region=S.egyptRegions.find(function(r){return r.id===regionId;});
  if(region){
    showToast((S.lang==='ar'?'المنطقة المختارة: ':'Selected region: ')+(S.lang==='ar'?region.nameAr:region.nameEn),'info');
  }
  if(S.view==='explore'){
    renderExplorePage();
  }
}

/* ===== PARTICLE BACKGROUND ANIMATION ===== */
function initParticles(){
  var canvas=document.createElement('canvas');
  canvas.style.cssText='position:fixed;inset:0;z-index:0;pointer-events:none;';
  canvas.setAttribute('aria-hidden','true');
  document.body.prepend(canvas);
  var ctx=canvas.getContext('2d'),w,h,pts=[];
  var prefersReducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function resize(){w=canvas.width=window.innerWidth;h=canvas.height=window.innerHeight;}
  resize();window.addEventListener('resize',resize);
  for(var i=0;i<35;i++){pts.push({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.5+0.5,dx:(Math.random()-0.5)*0.3,dy:(Math.random()-0.5)*0.3,o:Math.random()*0.3+0.1});}
  function draw(){
    ctx.clearRect(0,0,w,h);
    for(var i=0;i<pts.length;i++){
      var p=pts[i];ctx.beginPath();ctx.arc(p.x,p.y,Math.max(0.1,p.r),0,Math.PI*2);
      ctx.fillStyle='rgba(196,145,92,'+p.o+')';ctx.fill();
      p.x+=p.dx;p.y+=p.dy;
      if(p.x<0)p.x=w;if(p.x>w)p.x=0;if(p.y<0)p.y=h;if(p.y>h)p.y=0;
      for(var j=i+1;j<pts.length;j++){
        var dx=pts[i].x-pts[j].x,dy=pts[i].y-pts[j].y,d=Math.sqrt(dx*dx+dy*dy);
        if(d<150){ctx.beginPath();ctx.moveTo(pts[i].x,pts[i].y);ctx.lineTo(pts[j].x,pts[j].y);ctx.strokeStyle='rgba(196,145,92,'+(0.06*(1-d/150))+')';ctx.lineWidth=0.5;ctx.stroke();}
      }
    }
    requestAnimationFrame(draw);
  }
  if(!prefersReducedMotion)draw();
}

/* ===== SCROLL ANIMATIONS ===== */
function initScrollAnim(){
  var obs=new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      if(en.isIntersecting){en.target.style.animationPlayState='running';obs.unobserve(en.target);}
    });
  },{threshold:0.1});
  document.querySelectorAll('.fade-up').forEach(function(el){el.style.animationPlayState='paused';obs.observe(el);});
}

/* ===== CHAT SYSTEM ===== */
function getClientId(){
  if(!S.clientSessionId){
    try{
      var stored=localStorage.getItem('dof_chat_client_id');
      if(stored){S.clientSessionId=stored;}
    }catch(e){}
    if(!S.clientSessionId){
      S.clientSessionId='client_'+Date.now()+'_'+Math.random().toString(36).substr(2,6);
      try{localStorage.setItem('dof_chat_client_id',S.clientSessionId);}catch(e){}
    }
  }
  return S.clientSessionId;
}
function persistChatData(){
  if(apiToken()&&S.user)return;
  try{
    var data={conversations:S.conversations||[],messages:S.messages||{},blockedUsers:S.blockedUsers||[],reportedConversations:S.reportedConversations||[]};
    localStorage.setItem('dof_chat_data_v1',JSON.stringify(data));
  }catch(e){}
}
function loadChatData(){
  if(apiToken()&&S.user){
    S.conversations=[];
    S.messages={};
    S.blockedUsers=[];
    return;
  }
  try{
    var raw=localStorage.getItem('dof_chat_data_v1');
    if(raw){
      var data=JSON.parse(raw);
      S.conversations=data.conversations||[];
      S.messages=data.messages||{};
      S.blockedUsers=data.blockedUsers||[];
      S.reportedConversations=data.reportedConversations||[];
    }
  }catch(e){}
}
async function refreshConversations(){
  if(!apiToken()||!S.user)return;
  var data=await apiRequest('/api/conversations');
  S.conversations=(data.conversations||[]).map(normalizeConversation);
}
async function loadConversationMessages(convId){
  var conv=S.conversations.find(function(c){return String(c.id)===String(convId);});
  if(!conv)return [];
  if(!apiToken()||!S.user)return getConvMessages(convId);
  var data=await apiRequest('/api/conversations/'+convId+'/messages');
  var messages=(data.messages||[]).map(function(m){return normalizeMessage(m,conv);});
  setConvMessages(convId,messages);
  return messages;
}
function isConversationBlocked(conv){
  if(!conv)return false;
  return !!conv.blockedBy||S.blockedUsers.indexOf(conv.clientId)>-1||S.blockedUsers.indexOf('photo_'+conv.photographerId)>-1;
}
function getConvMessages(convId){
  return (S.messages[String(convId)]||[]);
}
function setConvMessages(convId,msgs){
  S.messages[String(convId)]=msgs;
}
function updateConvPreview(convId,lastMsg,timestamp){
  var conv=S.conversations.find(function(c){return c.id===convId;});
  if(conv){
    conv.lastMessage=lastMsg;
    conv.lastMessageAt=timestamp||new Date().toISOString();
  }
}
function getTotalUnread(){
  var total=0;
  var au=authUser();
  if(!au)return total;
  S.conversations.forEach(function(c){
    if(c.status==='active'||c.status==='archived'){
      if(c.photographerId===au.id&&(c.unread||0)>0){total+=c.unread||0;}
    }
  });
  return total;
}
function updateChatBadge(){
  var total=getTotalUnread();
  var fab=document.getElementById('chat-fab-badge');
  if(fab){
    if(total>0){fab.classList.remove('hidden');fab.textContent=total>99?'99+':total;}
    else{fab.classList.add('hidden');}
  }
  var sb=document.getElementById('sidebar-chat-badge');
  if(sb){
    if(total>0&&S.view==='dashboard'){sb.classList.remove('hidden');sb.textContent=total>99?'99+':total;}
    else{sb.classList.add('hidden');}
  }
}
function getConversationPeer(conv){
  var au=authUser();
  var asPhotographer=au&&au.role==='photographer'&&conv.photographerId===au.id;
  if(asPhotographer){
    return {
      name:conv.clientName||'Client',
      avatar:conv.clientAvatar||'https://picsum.photos/seed/client/80/80'
    };
  }
  return {
    name:conv.photographerName||'Photographer',
    avatar:conv.photographerAvatar||'https://picsum.photos/seed/conv/80/80'
  };
}
function syncChatPanelMode(){
  var panel=document.getElementById('chat-panel');
  if(!panel)return;
  var isClient=S.user&&S.user.role==='client';
  panel.classList.toggle('client-chat-panel',!!isClient);
}
function useClientWideChat(){
  var panel=document.getElementById('chat-panel');
  return !!(panel&&panel.classList.contains('client-chat-panel')&&window.innerWidth>=760);
}
function toggleChatPanel(){
  var panel=document.getElementById('chat-panel');
  var fab=document.getElementById('chat-fab');
  syncChatPanelMode();
  if(panel.classList.contains('open')){
    panel.classList.remove('open');
    fab.style.display='';
  } else {
    renderChatConvList();
    panel.classList.add('open');
    fab.style.display='none';
  }
}
function closeChatPanel(){
  document.getElementById('chat-panel').classList.remove('open');
  document.getElementById('chat-fab').style.display='';
}
function showChatConvList(){
  var convView=document.getElementById('chat-conv-view');
  var convList=document.getElementById('chat-conv-list');
  var panel=document.getElementById('chat-panel');
  if(panel)panel.classList.remove('chat-has-thread');
  if(convView){convView.style.display='none';convView.classList.add('hidden');}
  if(convList){convList.style.display='';convList.classList.remove('hidden');}
  S.chatActiveConv=null;
  renderChatConvList();
}
async function renderChatConvList(){
  var container=document.getElementById('chat-conv-list');
  var convView=document.getElementById('chat-conv-view');
  if(!container)return;
  if(apiToken()){await refreshConversations().catch(function(){});}
  syncChatPanelMode();
  var keepThread=!!(S.chatActiveConv&&useClientWideChat());
  var panel=document.getElementById('chat-panel');
  if(panel)panel.classList.toggle('chat-has-thread',keepThread);
  if(convView){convView.style.display=keepThread?'flex':'none';convView.classList.toggle('hidden',!keepThread);}
  container.style.display='';container.classList.remove('hidden');
  var convs=S.conversations||[];
  var au=authUser();
  var pId=au&&au.role==='photographer'?au.id:null;
  var cId=au&&au.role==='client'?au.id:getClientId();
  var filtered=convs.filter(function(c){
    if(pId){return c.photographerId===pId;}
    return c.clientId===cId;
  });
  filtered.sort(function(a,b){return new Date(b.lastMessageAt)-new Date(a.lastMessageAt);});
  var title=document.getElementById('chat-panel-title');
  if(title){title.textContent=t('chatTitle');}
  if(filtered.length===0){
    var emptyPanel=document.getElementById('chat-panel');
    if(emptyPanel)emptyPanel.classList.remove('chat-has-thread');
    container.innerHTML='<div class="chat-empty-state"><i class="fas fa-comment-dots"></i><div class="text-sm font-semibold">'+t('chatNoConvs')+'</div></div>';
    return;
  }
  container.innerHTML=filtered.map(function(c){
    var isBlocked=isConversationBlocked(c);
    var blockedLabel=isBlocked?'<span class="badge badge-cancelled" style="font-size:9px;padding:1px 6px;">'+t('chatBlocked')+'</span>':'';
    var peer=getConversationPeer(c);
    return'<div class="chat-conv-item'+(c.id===S.chatActiveConv?' selected':'')+'" onclick="openChatConversation(\''+c.id+'\')">'+
    '<img class="conv-avatar" src="'+peer.avatar+'" alt="">'+
    '<div class="info"><div class="name">'+peer.name+blockedLabel+'</div>'+
    '<div class="preview">'+(isBlocked?t('chatBlocked'):(c.lastMessage||''))+'</div></div>'+
    '<div class="meta">'+
    (c.unread>0?'<div class="unread-badge">'+(c.unread>99?'99+':c.unread)+'</div>':'')+
    '<div class="time-sm">'+timeAgo(c.lastMessageAt)+'</div></div></div>';
  }).join('');
  if(keepThread){openChatConversation(S.chatActiveConv);}
  updateChatBadge();
}
function timeAgo(iso){
  if(!iso)return'';
  var diff=Date.now()-new Date(iso).getTime();
  var mins=Math.floor(diff/60000);
  if(mins<1)return S.lang==='ar'?'الآن':'now';
  if(mins<60)return mins+(S.lang==='ar'?' د':'m');
  var hrs=Math.floor(mins/60);
  if(hrs<24)return hrs+(S.lang==='ar'?' س':'h');
  var days=Math.floor(hrs/24);
  if(days<7)return days+(S.lang==='ar'?' ي':'d');
  var d=new Date(iso);
  return S.lang==='ar'?d.toLocaleDateString('ar-EG',{month:'short',day:'numeric'}):d.toLocaleDateString('en-US',{month:'short',day:'numeric'});
}
async function renderChatMessages(skipFetch){
  var area=document.getElementById('chat-msg-area');
  if(!area||!S.chatActiveConv)return;
  var conv=S.conversations.find(function(c){return c.id===S.chatActiveConv;});
  if(!conv)return;
  if(apiToken()&&!skipFetch){
    try{
      await loadConversationMessages(S.chatActiveConv);
    }catch(e){}
  }
  var msgs=getConvMessages(S.chatActiveConv);
  var au=authUser();
  var pId=au&&au.role==='photographer'?au.id:null;
  var isClient=!(pId&&pId===conv.photographerId);
  var isBlocked=isConversationBlocked(conv);
  var inputArea=document.querySelector('#chat-panel-footer, .chat-panel-footer');
  var input=document.getElementById('chat-input');
  if(input){
    input.disabled=isBlocked;
    input.placeholder=isBlocked?t('chatBlocked'):t('chatInput');
  }
  if(msgs.length===0){
    area.innerHTML='<div class="chat-empty-state" style="padding:20px;"><i class="fas fa-comment" style="font-size:2rem;"></i><p style="font-size:13px;">'+t('chatNoMsg')+'</p></div>';
    return;
  }
  area.innerHTML=msgs.map(function(m){
    var isMine=(isClient&&m.sender==='client')||(!isClient&&m.sender==='photographer');
    if(m.deleted){
      return'<div class="chat-msg '+(m.sender==='photographer'?'photographer':'client')+' '+(isMine?'mine':'theirs')+'"><div class="bubble" style="opacity:0.4;font-style:italic;font-size:11px;"><i class="fas fa-trash-alt mr-1"></i>'+t('chatMsgDeleted')+'</div></div>';
    }
    var timeStr=formatClock(m.timestamp);
    return'<div class="chat-msg '+(m.sender==='photographer'?'photographer':'client')+' '+(isMine?'mine':'theirs')+'">'+
    '<div class="bubble">'+
    (isMine?'<div class="chat-msg-actions"><button onclick="deleteChatMessage(\''+m.id+'\')" title="'+t('chatDeleteMsg')+'"><i class="fas fa-trash-alt"></i></button></div>':'')+
    escapeHtml(m.content)+'<div class="time">'+timeStr+'</div></div></div>';
  }).join('');
  area.scrollTop=area.scrollHeight;
  /* Mark messages as read */
  if(!isClient&&conv.unread>0){
    conv.unread=0;
    updateChatBadge();
    updateChatConvListPreview();
    persistChatData();
  }
}
function updateChatConvListPreview(){
  var container=document.getElementById('chat-conv-list');
  if(container&&container.style.display!=='none'){renderChatConvList();}
}
function openChatConversation(convId){
  var conv=S.conversations.find(function(c){return c.id===convId;});
  if(!conv)return;
  S.chatActiveConv=convId;
  var container=document.getElementById('chat-conv-list');
  var convView=document.getElementById('chat-conv-view');
  var title=document.getElementById('chat-panel-title');
  var peer=getConversationPeer(conv);
  syncChatPanelMode();
  var panel=document.getElementById('chat-panel');
  if(panel)panel.classList.toggle('chat-has-thread',useClientWideChat());
  if(container){
    if(useClientWideChat()){container.style.display='';container.classList.remove('hidden');}
    else{container.style.display='none';container.classList.add('hidden');}
  }
  if(convView){convView.style.display='flex';convView.classList.remove('hidden');}
  if(title){title.textContent=t('convWith')+' '+peer.name;}
  var avatar=document.getElementById('chat-conv-avatar');
  if(avatar){avatar.src=peer.avatar;}
  var name=document.getElementById('chat-conv-name');
  if(name){name.textContent=peer.name;}
  var status=document.getElementById('chat-conv-status');
  if(status){
    var isBlocked=isConversationBlocked(conv);
    if(isBlocked){
      status.className='chat-header-status offline';status.innerHTML='<i class="fas fa-circle" style="font-size:6px;"></i><span>'+t('chatBlocked')+'</span>';
    }else{
      status.className='chat-header-status online';status.innerHTML='<i class="fas fa-circle" style="font-size:6px;"></i><span>'+t('chatOnline')+'</span>';
    }
  }
  var actions=document.querySelector('#chat-conv-header .chat-conv-actions');
  if(actions){
    var bookingAction=document.getElementById('chat-conv-booking-btn');
    if(!bookingAction){
      bookingAction=document.createElement('button');
      bookingAction.id='chat-conv-booking-btn';
      bookingAction.className='report-btn';
      bookingAction.type='button';
      bookingAction.onclick=openBookingForActiveChat;
      bookingAction.innerHTML='<i class="fas fa-calendar-plus mr-1"></i>'+(S.lang==='ar'?'حجز':'Book');
      actions.insertBefore(bookingAction,actions.firstChild);
    }
    var au=authUser();
    bookingAction.classList.toggle('hidden',!(au&&au.role==='photographer'&&conv.clientId));
  }
  renderChatMessages();
  updateChatBadge();
}
async function sendChatMessage(){
  if(!S.chatActiveConv)return;
  if(!apiToken()||!S.user){showToast(S.lang==='ar'?'يرجى تسجيل الدخول أولاً':'Please login first','error');return;}
  var input=document.getElementById('chat-input');
  var text=input.value.trim();
  if(!text)return;
  var conv=S.conversations.find(function(c){return c.id===S.chatActiveConv;});
  if(!conv)return;
  if(isConversationBlocked(conv)){showToast(t('chatBlocked'),'error');return;}
  input.disabled=true;
  try{
    var saved=await apiRequest('/api/conversations/'+S.chatActiveConv+'/messages',{method:'POST',body:{content:text}});
    var msg=normalizeMessage(saved.message,conv);
    var msgs=getConvMessages(S.chatActiveConv);
    msgs.push(msg);
    setConvMessages(S.chatActiveConv,msgs);
    input.value='';
  }catch(err){showToast(err.message||'تعذر إرسال الرسالة','error');return;}
  finally{input.disabled=false;}
  updateConvPreview(S.chatActiveConv,text,msg.timestamp);
  updateChatBadge();
  renderChatMessages(true);
  updateChatConvListPreview();
}
async function findOrCreateConversation(photographerId,photographerLink){
  var link=String(photographerLink||publicProfileLinkFromState()||publicProfileLinkFromUrl()||rememberedPublicPhotographerLink()||'').trim();
  if(apiToken()){
    photographerId=String(photographerId||'').trim();
    if(!link&&(!photographerId||!isUuidLike(photographerId))){
      photographerId=await resolvePhotographerIdForChat(photographerId,link);
    }
    if(!photographerId&&!link)return null;
    var body={};
    if(link)body.photographerLink=link;
    else if(photographerId&&isUuidLike(photographerId))body.photographerId=photographerId;
    else return null;
    var data=await apiRequest('/api/conversations',{method:'POST',body:body});
    var conv=normalizeConversation(data.conversation);
    var existingIndex=S.conversations.findIndex(function(c){return c.id===conv.id;});
    if(existingIndex>-1)S.conversations[existingIndex]=conv;else S.conversations.push(conv);
    return conv;
  }
  photographerId=await resolvePhotographerIdForChat(photographerId,link);
  if(!photographerId&&!link)return null;
  var clientId=getClientId();
  var existing=S.conversations.find(function(c){
    return c.photographerId===photographerId&&c.clientId===clientId;
  });
  if(existing)return existing;
  var photo=S.photographers.find(function(p){return p.id===photographerId;});
  if(!photo)return null;
  var conv={id:Date.now(),photographerId:photographerId,clientId:clientId,clientName:S.user?S.user.name||'Guest':'Guest',clientEmail:S.user?S.user.email:'',photographerName:gf(photo,'name')||'Photographer',photographerAvatar:photo.avatar||'https://picsum.photos/seed/conv/80/80',lastMessage:'',lastMessageAt:new Date().toISOString(),unread:0,status:'active',createdAt:new Date().toISOString(),blockedBy:null};
  S.conversations.push(conv);
  persistChatData();
  return conv;
}
async function resolvePhotographerIdForChat(photographerId,photographerLink){
  var id=String(photographerId||'').trim();
  var current=S.viewedPhotographer||{};
  var link=String(photographerLink||current.customLink||current.custom_link||publicProfileLinkFromUrl()||rememberedPublicPhotographerLink()||'').trim();
  if(S.user&&S.user.role==='client'&&id&&String(id)===String(S.user.id))id='';
  if(id&&(!apiToken()||isUuidLike(id)))return id;
  if(id&&apiToken()&&!isUuidLike(id)&&!link)return'';
  id=String(current.id||'').trim();
  if(S.user&&S.user.role==='client'&&id&&String(id)===String(S.user.id))id='';
  if(id&&(!apiToken()||isUuidLike(id)))return id;
  if(id&&apiToken()&&!isUuidLike(id)&&!link)return'';
  if(!link)return'';
  var data=await apiRequest('/api/photographers/'+encodeURIComponent(link));
  if(!setViewedPhotographerFromApi(data))return'';
  return String((S.viewedPhotographer||{}).id||'').trim();
}
async function ensurePublicProfileChatTarget(btn){
  var current=S.viewedPhotographer||{};
  var id=btn&&btn.dataset?btn.dataset.photographerId:'';
  var link=btn&&btn.dataset?btn.dataset.photographerLink:'';
  id=id||current.id||'';
  link=link||current.customLink||current.custom_link||publicProfileLinkFromUrl()||rememberedPublicPhotographerLink()||'';
  if(S.user&&S.user.role==='client'&&String(id)===String(S.user.id))id='';
  if(link&&!id){
    await hydrateViewedPhotographerFromLink(link).catch(function(){});
    current=S.viewedPhotographer||{};
    id=current.id||'';
    link=current.customLink||current.custom_link||link;
    if(S.user&&S.user.role==='client'&&String(id)===String(S.user.id))id='';
  }
  if(link)return{id:id,link:link};
  return{id:id,link:link};
}
async function startChatWithCurrentPhotographer(btn){
  var target=await ensurePublicProfileChatTarget(btn);
  if(!target.id&&!target.link){
    showToast(S.lang==='ar'?'تعذر تحديد المصور لبدء المحادثة':'Could not identify the photographer to message','error');
    return;
  }
  startChatWithPhotographer(target.id,target.link);
}
function stashPendingChatIntent(photographerId,photographerLink){
  var phFor=S.viewedPhotographer||{};
  var id=photographerId||phFor.id||'';
  if(S.user&&S.user.role==='client'&&String(id)===String(S.user.id))id='';
  var link=photographerLink||phFor.customLink||phFor.custom_link||publicProfileLinkFromUrl()||rememberedPublicPhotographerLink()||'';
  if(link)rememberPublicPhotographerLink(link);
  var intent={photographerId:id,photographerLink:link,savedAt:Date.now()};
  try{sessionStorage.setItem('dof_pending_chat_intent',JSON.stringify(intent));}catch(e){}
}
function restorePendingChatIntent(){
  if(!S.user||S.user.role!=='client')return false;
  var raw='';try{raw=sessionStorage.getItem('dof_pending_chat_intent')||'';}catch(e){return false;}
  if(!raw)return false;
  var intent;try{intent=JSON.parse(raw);}catch(e){return false;}
  try{sessionStorage.removeItem('dof_pending_chat_intent');}catch(e){}
  if(!intent||!intent.savedAt||Date.now()-intent.savedAt>30*60*1000)return false;
  if(!intent.photographerId&&!intent.photographerLink)return false;
  setTimeout(function(){startChatWithPhotographer(intent.photographerId,intent.photographerLink);},80);
  return true;
}
async function startChatWithPhotographer(photographerId,photographerLink){
  if(!S.user||!apiToken()){
    stashPendingChatIntent(photographerId,photographerLink);
    setAuthRole('client');
    switchAuthTab('login');
    openModal('auth-modal');
    showToast(S.lang==='ar'?'يرجى تسجيل الدخول أولاً':'Please login first','info');
    return;
  }
  if(S.user.role!=='client'){
    showToast(S.lang==='ar'?'الرسائل من صفحة المصور متاحة لحسابات العملاء فقط':'Please sign in as a client to message photographers','error');
    return;
  }
  var targetId;
  var targetLink=String(photographerLink||publicProfileLinkFromState()||publicProfileLinkFromUrl()||rememberedPublicPhotographerLink()||'').trim();
  try{targetId=await resolvePhotographerIdForChat(photographerId,targetLink);}
  catch(err){showToast(err.message||'Could not identify photographer','error');return;}
  if(!targetId&&!targetLink){
    showToast(S.lang==='ar'?'تعذر تحديد المصور لبدء المحادثة':'Could not identify the photographer to message','error');
    return;
  }
  var conv;
  try{conv=await findOrCreateConversation(targetId,targetLink);}catch(err){showToast(err.message||'Could not start conversation','error');return;}
  if(!conv){showToast('تعذر فتح المحادثة','error');return;}
  if(S.view==='public'||S.view==='landing'){
    var panel=document.getElementById('chat-panel');
    if(panel){
      syncChatPanelMode();
      panel.classList.add('open');
    }
    var fab=document.getElementById('chat-fab');
    if(fab)fab.style.display='none';
  }
  openChatConversation(conv.id);
}
function renderChatDashboard(){
  var convs=S.conversations||[];
  var au=authUser();
  var pId=au&&au.role==='photographer'?au.id:null;
  var cId=au&&au.role==='client'?au.id:null;
  var filtered=convs.filter(function(c){
    if(pId) return String(c.photographerId)===String(pId);
    if(cId) return String(c.clientId)===String(cId);
    return false;
  });
  filtered.sort(function(a,b){return new Date(b.lastMessageAt)-new Date(a.lastMessageAt);});
  var totalUnread=filtered.reduce(function(sum,c){return sum+(c.unread||0);},0);
  
  var html='<div class="flex justify-between items-center mb-6"><h2 class="text-2xl font-bold">'+
    (S.lang==='ar'?'الرسائل':'Messages')+' '+
    (totalUnread>0?'<span class="badge badge-confirmed text-sm ml-2">'+totalUnread+' '+(S.lang==='ar'?'غير مقروءة':'unread')+'</span>':'')+
    '</h2></div>';
  
  if(filtered.length===0){
    return html+'<div class="empty-state"><i class="fas fa-comment-dots"></i><h3 class="text-lg font-semibold mb-2">'+
      (S.lang==='ar'?'لا توجد محادثات':'No conversations yet')+'</h3><p class="text-sm">'+
      (S.lang==='ar'?'عندما يتواصل معك العملاء، ستظهر محادثاتهم هنا':'When clients contact you, their conversations will appear here')+'</p></div>';
  }
  
  html+='<div class="space-y-3">'+filtered.map(function(c){
    var isBlocked=isConversationBlocked(c);
    var peer=getConversationPeer(c);
    var msgs=getConvMessages(c.id);
    var lastMsg=msgs.length>0?msgs[msgs.length-1]:null;
    var lastContent=lastMsg&&!lastMsg.deleted?lastMsg.content:(c.lastMessage||(S.lang==='ar'?'بدون رسائل':'No messages'));
    var lastTime=lastMsg?timeAgo(lastMsg.timestamp):timeAgo(c.lastMessageAt);
    var isOnline=Math.random()>0.5;
    return'<div class="card p-4 hover:border-[var(--accent)] cursor-pointer" onclick="openChatByConv(\''+c.id+'\')">'+
    '<div class="flex items-start gap-3"><img src="'+peer.avatar+'" class="w-12 h-12 rounded-xl object-cover border border-[var(--border)]" alt="">'+
    '<div class="flex-1 min-w-0"><div class="flex items-center justify-between gap-2"><div class="font-semibold flex items-center gap-2">'+
    peer.name+
    (isBlocked?'<span class="badge badge-cancelled">'+t('chatBlocked')+'</span>':'')+
    '</div><div class="text-xs text-[var(--text2)] whitespace-nowrap">'+lastTime+'</div></div>'+
    '<div class="text-sm text-[var(--text2)] truncate mt-1">'+lastContent+'</div></div>'+
    '<div class="flex flex-col items-center gap-2 flex-shrink-0">'+
    (c.unread>0?'<span class="unread-badge">'+(c.unread>99?'99+':c.unread)+'</span>':'')+
    '<span class="chat-header-status '+(isOnline?'online':'offline')+'"><i class="fas fa-circle" style="font-size:6px;"></i></span></div></div>'+
    '<div class="flex gap-2 mt-3 pt-3 border-t border-[var(--border)]" onclick="event.stopPropagation()">'+
    '<button onclick="openChatModal(\''+c.id+'\')" class="btn-primary btn-sm" style="padding:4px 10px;font-size:11px;"><i class="fas fa-comment-dots ml-1"></i>محادثة</button>'+
    (isBlocked?'<button onclick="unblockUser(\''+c.clientId+'\')" class="btn-success btn-sm" style="padding:4px 10px;font-size:11px;"><i class="fas fa-check mr-1"></i>'+t('chatUnblock')+'</button>':
    '<button onclick="blockUserFromDashboard(\''+c.clientId+'\')" class="btn-danger btn-sm" style="padding:4px 10px;font-size:11px;"><i class="fas fa-ban mr-1"></i>'+t('chatBlock')+'</button>')+
    '<button onclick="clearConversation(\''+c.id+'\')" class="btn-secondary btn-sm" style="padding:4px 10px;font-size:11px;color:var(--danger);border-color:var(--danger);"><i class="fas fa-trash-alt mr-1"></i>'+t('chatDeleteAll')+'</button>'+
    '</div></div>';
  }).join('')+'</div>';
  
  return html;
}
function openChatByConv(convId){
  S.chatActiveConv=convId;
  var conv=S.conversations.find(function(c){return c.id===convId;});
  var au=authUser();
  if(conv&&au&&conv.photographerId===au.id)conv.unread=0;
  updateChatBadge();
  /* Navigate to the chat panel if on mobile */
  var convView=document.getElementById('chat-conv-view');
  if(convView){
    document.getElementById('chat-conv-list').style.display='none';
    document.getElementById('chat-conv-list').classList.add('hidden');
    convView.style.display='flex';
    convView.classList.remove('hidden');
    openChatConversation(convId);
    renderChatMessages();
  }
}
async function archiveConversation(convId){
  var conv=S.conversations.find(function(c){return c.id===convId;});
  if(conv){
    var next=conv.status!=='archived';
    if(apiToken())await apiRequest('/api/conversations/'+convId+'/archive',{method:'PATCH',body:{archived:next}}).catch(function(e){showToast(e.message,'error');});
    conv.status=next?'archived':'active';
    persistChatData();
    renderTab();
    showToast(conv.status==='archived'?t('chatArchive'):t('chatUnarchive'),'info');
  }
}
async function blockUserFromDashboard(clientId){
  if(S.blockedUsers.indexOf(clientId)===-1)S.blockedUsers.push(clientId);
  var conv=S.conversations.find(function(c){return c.clientId===clientId;});
  if(apiToken()&&conv){
    await apiRequest('/api/conversations/'+conv.id+'/block',{method:'PATCH',body:{blocked:true}}).catch(function(e){showToast(e.message,'error');});
    conv.blockedBy=(authUser()||{}).id||conv.blockedBy;
  }
  persistChatData();
  renderTab();
  showToast(t('chatBlockSuccess'),'success');
}
async function unblockUser(clientId){
  S.blockedUsers=S.blockedUsers.filter(function(id){return id!==clientId;});
  var conv=S.conversations.find(function(c){return c.clientId===clientId;});
  if(apiToken()&&conv){
    await apiRequest('/api/conversations/'+conv.id+'/block',{method:'PATCH',body:{blocked:false}}).catch(function(e){showToast(e.message,'error');});
    if(conv.blockedBy===(authUser()||{}).id)conv.blockedBy=null;
  }
  persistChatData();
  if(S.tab==='chat')renderTab();
  else renderChatConvList();
  updateChatBadge();
  showToast(S.lang==='ar'?'تم إلغاء الحظر':'User unblocked','success');
}
function blockConversation(){
  if(!S.chatActiveConv)return;
  var conv=S.conversations.find(function(c){return c.id===S.chatActiveConv;});
  if(!conv)return;
  openModal('chat-block-modal');
}
async function confirmBlockConversation(){
  if(!S.chatActiveConv)return;
  var conv=S.conversations.find(function(c){return c.id===S.chatActiveConv;});
  if(!conv){closeModal('chat-block-modal');return;}
  if(S.blockedUsers.indexOf(conv.clientId)===-1)S.blockedUsers.push(conv.clientId);
  if(apiToken()){
    await apiRequest('/api/conversations/'+conv.id+'/block',{method:'PATCH',body:{blocked:true}}).catch(function(e){showToast(e.message,'error');});
    conv.blockedBy=(authUser()||{}).id||conv.blockedBy;
  }
  persistChatData();
  closeModal('chat-block-modal');
  showToast(t('chatBlockSuccess'),'success');
  renderChatMessages();
  updateChatBadge();
}
function reportConversation(){
  if(!S.chatActiveConv)return;
  var conv=S.conversations.find(function(c){return c.id===S.chatActiveConv;});
  if(!conv)return;
  openModal('chat-report-modal');
}
async function submitReport(){
  var selected=document.querySelector('input[name="report-reason"]:checked');
  if(!selected){showToast(S.lang==='ar'?'يرجى اختيار سبب البلاغ':'Please select a reason','error');return;}
  if(!S.chatActiveConv){closeModal('chat-report-modal');return;}
  var reason=selected.value;
  if(apiToken())await apiRequest('/api/reports',{method:'POST',body:{reason:reason,conversationId:S.chatActiveConv}}).catch(function(e){showToast(e.message,'error');});
  if(S.reportedConversations.indexOf(S.chatActiveConv)===-1)S.reportedConversations.push(S.chatActiveConv);
  persistChatData();
  closeModal('chat-report-modal');
  showToast(t('chatReportSuccess'),'success');
}
function deleteChatMessage(msgId){
  S.chatDeleteTargetMsgId=msgId;
  openModal('chat-delete-msg-modal');
}
async function confirmDeleteChatMessage(){
  if(!S.chatActiveConv||!S.chatDeleteTargetMsgId){closeModal('chat-delete-msg-modal');return;}
  var convId=S.chatActiveConv,msgId=S.chatDeleteTargetMsgId;
  closeModal('chat-delete-msg-modal');
  S.chatDeleteTargetMsgId=null;
  try{
    await apiRequest('/api/conversations/'+convId+'/messages/'+msgId,{method:'DELETE'});
  }catch(e){showToast(e.message||'فشل حذف الرسالة','error');return;}
  var msgs=getConvMessages(convId);
  var msg=msgs.find(function(m){return String(m.id)===String(msgId);});
  if(msg){msg.deleted=true;}
  setConvMessages(convId,msgs);
  persistChatData();
  renderChatMessages();
  if(document.getElementById('chat-modal')&&!document.getElementById('chat-modal').classList.contains('hidden')){renderChatModalMessages(getConvMessages(convId));}
  updateChatConvListPreview();
  showToast(t('chatMsgDeleted'),'info');
}
function clearConversation(convId){
  if(!confirm(S.lang==='ar'?'سيتم حذف جميع رسائل هذه المحادثة. هل أنت متأكد؟':'This will delete all messages in this conversation. Are you sure?'))return;
  S.conversations=S.conversations.filter(function(c){return c.id!==convId;});
  delete S.messages[String(convId)];
  persistChatData();
  renderTab();
  showToast(t('chatMsgDeleted'),'info');
}
/* ===== FULL-SCREEN CHAT MODAL ===== */
async function openChatModal(convId){
  var conv=S.conversations.find(function(c){return String(c.id)===String(convId);});
  if(!conv)return;
  S.chatActiveConv=convId;
  var modal=document.getElementById('chat-modal');
  if(!modal)return;
  var peer=getConversationPeer(conv);
  var avatarEl=document.getElementById('chat-modal-avatar');
  var nameEl=document.getElementById('chat-modal-name');
  var bookingBtn=document.getElementById('chat-modal-booking-btn');
  if(avatarEl){avatarEl.src=peer.avatar||'https://picsum.photos/seed/chat/80/80';}
  if(nameEl){nameEl.textContent=peer.name;}
  if(bookingBtn){
    var au=authUser();
    bookingBtn.classList.toggle('hidden',!(au&&au.role==='photographer'&&conv.clientId));
  }
  modal.classList.remove('hidden');
  document.body.style.overflow='hidden';
  try{
    await loadConversationMessages(convId);
  }catch(e){}
  renderChatModalMessages(getConvMessages(convId));
  var input=document.getElementById('chat-modal-input');
  if(input)setTimeout(function(){input.focus();},100);
}
function closeChatModal(){
  var modal=document.getElementById('chat-modal');
  if(modal)modal.classList.add('hidden');
  document.body.style.overflow='';
}
function handleChatModalBackdrop(e){
  if(e.target===document.getElementById('chat-modal'))closeChatModal();
}
function openBookingForActiveChat(){
  var conv=S.conversations.find(function(c){return String(c.id)===String(S.chatActiveConv);});
  if(!conv||!conv.clientId){
    showToast(S.lang==='ar'?'هذه المحادثة غير مرتبطة بحساب عميل':'This conversation is not linked to a client account','error');
    return;
  }
  closeChatModal();
  openAptModal(conv.clientId);
}
function renderChatModalMessages(msgs){
  var area=document.getElementById('chat-modal-messages');
  if(!area)return;
  var au=authUser();
  var myId=au?au.id:null;
  var conv=S.conversations.find(function(c){return String(c.id)===String(S.chatActiveConv);});
  if(!msgs||!msgs.length){area.innerHTML='<div class="text-center text-[var(--text2)] text-sm py-8">'+t('chatNoMsg')+'</div>';return;}
  area.innerHTML=msgs.map(function(m){
    var isMine=conv&&(m.sender==='photographer'?(au&&au.role==='photographer'):(au&&au.role==='client'));
    var content=m.deleted?'<span class="text-[var(--text2)] italic text-sm">'+t('chatMsgDeleted')+'</span>':escapeHtml(m.content);
    var align=isMine?'items-end':'items-start';
    var bubble=isMine?'bg-[var(--accent)] text-white':'bg-[var(--bg2)] text-[var(--text)]';
    var time=m.timestamp?formatClock(m.timestamp):'';
    return'<div class="flex flex-col '+align+'">'+
      '<div class="'+bubble+' rounded-2xl px-4 py-2 max-w-[70%] text-sm leading-relaxed">'+content+'</div>'+
      '<div class="text-xs text-[var(--text2)] mt-1 px-1">'+time+'</div>'+
    '</div>';
  }).join('');
  area.scrollTop=area.scrollHeight;
}
async function sendChatModalMessage(){
  var input=document.getElementById('chat-modal-input');
  var text=input?input.value.trim():'';
  if(!text||!S.chatActiveConv)return;
  if(!apiToken()||!S.user){showToast(S.lang==='ar'?'يرجى تسجيل الدخول أولاً':'Please login first','error');return;}
  input.value='';
  input.disabled=true;
  var conv=S.conversations.find(function(c){return String(c.id)===String(S.chatActiveConv);});
  if(!conv){input.disabled=false;return;}
  try{
    var data=await apiRequest('/api/conversations/'+S.chatActiveConv+'/messages',{method:'POST',body:{content:text}});
    var msg=normalizeMessage(data.message,conv);
    var msgs=getConvMessages(S.chatActiveConv);
    msgs.push(msg);
    setConvMessages(S.chatActiveConv,msgs);
    updateConvPreview(S.chatActiveConv,text,msg.timestamp);
    renderChatModalMessages(msgs);
  }catch(e){showToast(e.message||'فشل إرسال الرسالة','error');input.value=text;}
  finally{input.disabled=false;}
}
function escapeHtml(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function jsString(s){return String(s||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/\r/g,'').replace(/\n/g,'\\n');}
/* ===== END CHAT MODAL ===== */

function initChatSystem(){
  if(apiToken()&&S.user){
    S.conversations=[];
    S.messages={};
    S.blockedUsers=[];
    refreshConversations().then(function(){updateChatBadge();}).catch(function(){});
  }else{
    loadChatData();
    if(!S.clientSessionId)getClientId();
  }
  setupChatFAB();
  updateChatBadge();
  /* Listen for localStorage changes from other tabs */
  window.addEventListener('storage',function(e){
    if(apiToken()&&S.user)return;
    if(e.key==='dof_chat_data_v1'){
      loadChatData();
      if(S.chatActiveConv){renderChatMessages();}
      else {renderChatConvList();}
      updateChatBadge();
    }
  });
  initRealtimePolling();
}
/* ===== LIGHTWEIGHT POLLING =====
   Keeps booking statuses and chat conversations in sync without WebSockets.
   Bookings poll every 30s, conversations every 20s, but only when:
     - the user is logged in (apiToken() is present)
     - the tab is visible (skip background tabs to save battery/quota)
*/
var _pollIntervals={bookings:null,convs:null,messages:null,support:null};
function initRealtimePolling(){
  if(_pollIntervals.bookings)clearInterval(_pollIntervals.bookings);
  if(_pollIntervals.convs)clearInterval(_pollIntervals.convs);
  if(_pollIntervals.messages)clearInterval(_pollIntervals.messages);
  if(_pollIntervals.support)clearInterval(_pollIntervals.support);
  _pollIntervals.bookings=setInterval(pollBookings,30000);
  _pollIntervals.convs=setInterval(pollConversations,20000);
  _pollIntervals.messages=setInterval(pollActiveMessages,10000);
  _pollIntervals.support=setInterval(pollSupportChat,12000);
}
async function pollBookings(){
  if(!apiToken()||!S.user)return;
  if(document.visibilityState==='hidden')return;
  try{
    var prev=JSON.stringify(S.bookings.map(function(b){return {id:b.id,status:b.status};}));
    await refreshMyBookings();
    var next=JSON.stringify(S.bookings.map(function(b){return {id:b.id,status:b.status};}));
    if(prev===next)return;
    if(S.view==='dashboard'&&(S.tab==='bookings'||S.tab==='overview'||S.tab==='calendar'))renderTab();
    else if(S.view==='landing'&&S.user.role==='client')renderClientBookingsPanel();
  }catch(e){}
}
async function pollConversations(){
  if(!apiToken()||!S.user)return;
  if(document.visibilityState==='hidden')return;
  try{
    var prev=JSON.stringify(S.conversations.map(function(c){return {id:c.id,last:c.lastMessageAt,unread:c.unread};}));
    await refreshConversations();
    var next=JSON.stringify(S.conversations.map(function(c){return {id:c.id,last:c.lastMessageAt,unread:c.unread};}));
    updateChatBadge();
    if(prev===next)return;
    if(S.view==='dashboard'&&S.tab==='chat')renderTab();
    var modal=document.getElementById('chat-modal');
    if(modal&&!modal.classList.contains('hidden')&&S.chatActiveConv){
      var conv=S.conversations.find(function(c){return String(c.id)===String(S.chatActiveConv);});
      if(conv){
        await loadConversationMessages(S.chatActiveConv);
        renderChatModalMessages(getConvMessages(S.chatActiveConv));
      }
    }
  }catch(e){}
}
async function pollActiveMessages(){
  if(!apiToken()||!S.user||!S.chatActiveConv)return;
  if(document.visibilityState==='hidden')return;
  var panel=document.getElementById('chat-panel');
  var modal=document.getElementById('chat-modal');
  var panelOpen=panel&&panel.classList.contains('open');
  var modalOpen=modal&&!modal.classList.contains('hidden');
  if(!panelOpen&&!modalOpen)return;
  try{
    var before=JSON.stringify(getConvMessages(S.chatActiveConv).map(function(m){return {id:m.id,deleted:m.deleted,content:m.content};}));
    await loadConversationMessages(S.chatActiveConv);
    var after=JSON.stringify(getConvMessages(S.chatActiveConv).map(function(m){return {id:m.id,deleted:m.deleted,content:m.content};}));
    if(before===after)return;
    if(modalOpen)renderChatModalMessages(getConvMessages(S.chatActiveConv));
    else renderChatMessages(true);
    updateChatConvListPreview();
  }catch(e){}
}
async function manualRefreshBookings(){
  if(!apiToken())return;
  try{
    await refreshMyBookings();
    renderTab();
    showToast('تم التحديث','success');
  }catch(e){showToast('فشل التحديث','error');}
}

/* ===== SUPPORT CHAT ===== */
function normalizeSupportConversation(row){
  row=row||{};
  return {
    id:row.id,userId:row.user_id,adminId:row.assigned_admin_id||null,status:row.status||'open',
    subject:row.subject||'Support',lastMessage:row.last_message||'',lastMessageAt:row.last_message_at||row.created_at,
    userName:row.user_name||'User',userEmail:row.user_email||'',adminName:row.admin_name||'Support'
  };
}
function normalizeSupportMessage(row){
  row=row||{};
  return {
    id:row.id,conversationId:row.support_conversation_id,senderId:row.sender_id,
    senderName:row.sender_name||'User',senderRole:row.sender_role||'',content:row.content||'',
    timestamp:row.created_at,deleted:row.is_deleted===true
  };
}
async function ensureSupportConversation(){
  if(!apiToken()||!S.user)throw new Error(S.lang==='ar'?'يرجى تسجيل الدخول أولاً':'Please login first');
  if(S.supportConversation&&S.supportConversation.status==='open')return S.supportConversation;
  var existing=await apiRequest('/api/support/conversations').catch(function(){return{conversations:[]};});
  var rows=(existing.conversations||[]).map(normalizeSupportConversation);
  var open=rows.find(function(c){return c.status==='open';})||rows[0];
  if(open){S.supportConversation=open;return open;}
  var created=await apiRequest('/api/support/conversations',{method:'POST',body:{subject:S.lang==='ar'?'دعم العملاء':'Customer support'}});
  S.supportConversation=normalizeSupportConversation(created.conversation);
  return S.supportConversation;
}
async function loadSupportMessages(){
  var conv=await ensureSupportConversation();
  var data=await apiRequest('/api/support/conversations/'+conv.id+'/messages');
  S.supportMessages=(data.messages||[]).map(normalizeSupportMessage);
  return S.supportMessages;
}
function supportLabels(){
  return S.lang==='ar'
    ?{title:'دعم العملاء',subtitle:'تحدث مباشرة مع فريق DOF STUDIOS',empty:'اكتب رسالتك وسيصلك الرد هنا.',input:'اكتب رسالتك...',send:'إرسال',login:'سجل الدخول أولاً للتواصل مع الدعم'}
    :{title:'Customer Support',subtitle:'Talk directly with the DOF STUDIOS team',empty:'Write your message and the reply will appear here.',input:'Type your message...',send:'Send',login:'Sign in first to contact support'};
}
function renderSupportChat(){
  var labels=supportLabels();
  var overlay=document.getElementById('support-chat-overlay');
  if(!overlay){
    overlay=document.createElement('div');
    overlay.id='support-chat-overlay';
    overlay.className='support-chat-overlay';
    overlay.onclick=function(e){if(e.target===overlay)closeSupportChat();};
    document.body.appendChild(overlay);
  }
  var mineId=S.user&&S.user.id;
  
  // Priority Support Badge for Premium users
  var priorityBadge='';
  if(S.user&&S.user.role==='photographer'&&activePlan()==='premium'){
    priorityBadge='<span class="dof-badge" style="font-size:11px;padding:4px 10px;margin-right:8px;background:linear-gradient(135deg,#EF4444,#F59E0B);animation:pulse-glow 2s infinite"><i class="fas fa-bolt" style="font-size:10px;margin-left:4px"></i>دعم أولوية</span>';
  }
  
  overlay.innerHTML='<div class="support-chat-pane" onclick="event.stopPropagation()">'+
    '<div class="support-chat-head"><div><div class="support-chat-kicker">DOF STUDIOS '+priorityBadge+'</div><h3>'+labels.title+'</h3><p>'+labels.subtitle+'</p></div><button type="button" class="support-chat-close" onclick="closeSupportChat()" aria-label="Close"><i class="fas fa-xmark"></i></button></div>'+
    '<div class="support-chat-body" id="support-chat-body">'+
      (S.supportLoading?'<div class="support-chat-empty"><i class="fas fa-spinner fa-spin"></i></div>':(S.supportMessages&&S.supportMessages.length?S.supportMessages.map(function(m){
        var mine=String(m.senderId||'')===String(mineId||'');
        return'<div class="support-msg '+(mine?'mine':'theirs')+'"><div class="support-bubble">'+escapeHtml(m.content)+'<div class="support-time">'+formatClock(m.timestamp)+'</div></div></div>';
      }).join(''):'<div class="support-chat-empty"><i class="fas fa-headset"></i><p>'+labels.empty+'</p></div>'))+
    '</div>'+
    '<form class="support-chat-compose" onsubmit="sendSupportChatMessage(event)"><input id="support-chat-input" type="text" placeholder="'+labels.input+'" autocomplete="off"><button type="submit"><i class="fas fa-paper-plane"></i><span>'+labels.send+'</span></button></form>'+
  '</div>';
  overlay.classList.add('open');
  document.body.classList.add('support-chat-open');
  document.body.style.overflow='hidden';
  var body=document.getElementById('support-chat-body');
  if(body)body.scrollTop=body.scrollHeight;
}
async function startSupportChat(e){
  if(e&&e.preventDefault)e.preventDefault();
  if(!apiToken()||!S.user){
    showToast(supportLabels().login,'info');
    setAuthRole('client');
    switchAuthTab('login');
    openModal('auth-modal');
    return;
  }
  S.supportOpen=true;
  S.supportLoading=true;
  renderSupportChat();
  try{
    await loadSupportMessages();
  }catch(err){
    showToast(err.message||'Support unavailable','error');
  }finally{
    S.supportLoading=false;
    renderSupportChat();
    var input=document.getElementById('support-chat-input');
    if(input)setTimeout(function(){input.focus();},60);
  }
}
function openDashboardSupport(e){
  if(e&&e.preventDefault)e.preventDefault();
  startSupportChat(e);
  var sidebar=document.getElementById('sidebar');
  var overlay=document.getElementById('sidebar-overlay');
  if(window.innerWidth<1024){
    if(sidebar)sidebar.classList.remove('open');
    if(overlay)overlay.classList.add('hidden');
  }
}
function closeSupportChat(){
  S.supportOpen=false;
  var overlay=document.getElementById('support-chat-overlay');
  if(overlay)overlay.classList.remove('open');
  document.body.classList.remove('support-chat-open');
  document.body.style.overflow='';
}
async function sendSupportChatMessage(e){
  if(e&&e.preventDefault)e.preventDefault();
  var input=document.getElementById('support-chat-input');
  var text=input?input.value.trim():'';
  if(!text)return;
  input.disabled=true;
  try{
    var conv=await ensureSupportConversation();
    var data=await apiRequest('/api/support/conversations/'+conv.id+'/messages',{method:'POST',body:{content:text}});
    S.supportMessages.push(normalizeSupportMessage(data.message));
    input.value='';
    renderSupportChat();
  }catch(err){
    showToast(err.message||'تعذر إرسال الرسالة','error');
  }finally{
    var nextInput=document.getElementById('support-chat-input');
    if(nextInput){nextInput.disabled=false;nextInput.focus();}
  }
}
async function pollSupportChat(){
  if(!S.supportOpen||!apiToken()||!S.user||!S.supportConversation)return;
  if(document.visibilityState==='hidden')return;
  try{
    var before=JSON.stringify((S.supportMessages||[]).map(function(m){return m.id;}));
    await loadSupportMessages();
    var after=JSON.stringify((S.supportMessages||[]).map(function(m){return m.id;}));
    if(before!==after)renderSupportChat();
  }catch(e){}
}
/* Expose init for use after login */
function setupChatFAB(){
  var fab=document.getElementById('chat-fab');
  if(!fab)return;
  syncChatPanelMode();
  if(S.view==='public'&&S.user&&S.user.role==='client'){
    fab.classList.remove('hidden');
  } else if(S.view==='landing'&&S.user&&S.user.role==='client'){
    fab.classList.remove('hidden');
  } else {
    fab.classList.add('hidden');
  }
}

function loadDemoPhotographer(){
  if(S.viewedPhotographer)return;
  if(S.user&&(S.user.role==='photographer'||S.user.role==='client'))return;
  var photo=S.photographers[0];
  if(!photo)return;
  S.user=deepCopy(photo);
  S.user.role='photographer';
  S.appointments=[];
  S.bookings=[];
  S.portfolio=deepCopy(photo.portfolio||[]);
  S.portfolioPublished=deepCopy(photo.portfolio||[]);
  S.portfolioDirty=false;
  S.isPortfolioPreview=false;
  S.packages=deepCopy(photo.packages||[]);
}
async function initializeCurrentPage(){
  restoreFrontendSession();
  await hydrateSiteContent();
  await hydrateCategories();
  if(apiToken())await hydrateAuthenticatedState();
  else{
    var storedProfile=readApiProfile();
    if(storedProfile)S.user=normalizeProfile(storedProfile);
  }
  applyTranslations();
  var view=getPageView();
  S.view=view;
  if(view==='explore')loadExploreFilterFromUrl();
  if(view==='public')await ensurePublicProfileHydrated();
  if(view==='dashboard'&&apiToken()&&(!S.user||S.user.role!=='photographer')){navigate('landing');return;}
  if(view==='clientdashboard'&&apiToken()&&(!S.user||S.user.role!=='client')){navigate('landing');return;}
  if(view==='dashboard'||(view==='public'&&!S.viewedPhotographer)){loadDemoPhotographer();}
  navigate(view);
}

/* ===== INITIALIZATION ===== */
function applyTranslations(){
  document.documentElement.lang=S.lang;
  document.documentElement.dir=S.lang==='ar'?'rtl':'ltr';
  document.querySelectorAll('[data-t]').forEach(function(el){
    var k=el.getAttribute('data-t');
    if(T[S.lang][k])el.textContent=T[S.lang][k];
  });
}
document.addEventListener('DOMContentLoaded',function(){
  applyTranslations();
  initializeCurrentPage().then(function(){initParticles();initScrollAnim();initChatSystem();});
});


/* ===== SUBSCRIPTION: MANUAL PAYMENT SYSTEM ===== */
async function handleActivateTrial(){
  if(!apiToken()){openModal('auth-modal');return;}
  try{
    showToast('جار تفعيل التجربة المجانية...','info');
    var data=await apiRequest('/api/subscriptions/activate-trial',{method:'POST'});
    if(data.success){
      showToast('تم تفعيل التجربة المجانية! 🎉','success');
      await hydrateAuthenticatedState();
      renderTab();
    }
  }catch(err){
    showToast(err.message||'تعذر تفعيل التجربة المجانية','error');
  }
}

function openManualPaymentModal(planCode){
  if(!apiToken()){openModal('auth-modal');return;}
  S.selectedPlanForPayment=planCode;
  var modal=document.getElementById('manual-payment-modal');
  if(!modal){
    var modalHTML='<div id="manual-payment-modal" class="modal-overlay">'+
      '<div class="modal-box lg">'+
      '<div class="flex justify-between items-center mb-6">'+
      '<h3 class="text-xl font-bold">الدفع اليدوي</h3>'+
      '<button onclick="closeManualPaymentModal()" class="text-[var(--text2)] hover:text-[var(--text)] text-xl">'+
      '<i class="fas fa-times"></i></button>'+
      '</div>'+
      '<div id="manual-payment-content"></div>'+
      '</div></div>';
    document.body.insertAdjacentHTML('beforeend',modalHTML);
    modal=document.getElementById('manual-payment-modal');
  }
  renderManualPaymentForm();
  openModal('manual-payment-modal');
}

